BEGIN;
SET search_path TO public;

-- Preguntas 2701 a 2800
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (2701, 'SUB-2701', 'SBM5', 'SEGÚN EL ARTÍCULO 180 MODIFICADO DEL CÓDIGO PROCESAL PENAL, ¿CUÁNDO PUEDEN LAS PARTES PRESENTAR OBSERVACIONES AL INFORME PERICIAL OFICIAL, Y BAJO QUÉ PRINCIPIO SE FUNDAMENTA ESTE DERECHO PROCESAL?', 'EN UN PLAZO IGUAL AL OTORGADO AL PERITO OFICIAL, DESPUÉS DE LA COMUNICACIÓN A LAS PARTES JUNTO CON COPIA DEL INFORME Y ANEXOS, FUNDAMENTÁNDOSE EN EL PRINCIPIO DE IGUALDAD PROCESAL.', 'ART. ÚNICO art. 180', '184894'),
    (2702, 'SUB-2702', 'SBM5', 'RESPECTO A LA PRESENTACIÓN DEL INFORME PERICIAL OFICIAL SEGÚN LA LEY 32130, ¿CUÁL ES EL MECANISMO PREVISTO CUANDO EXISTEN VARIOS PERITOS OFICIALES, PERO ENTRE ELLOS NO EXISTE UNANIMIDAD EN SUS CONCLUSIONES?:', 'CADA PERITO OFICIAL QUE DISCREPE DEBE PRESENTAR SU PROPIO INFORME PERICIAL.', 'ART. ÚNICO art. 180', '184895'),
    (2703, 'SUB-2703', 'SBM5', '¿CUÁL ES LA CONDICIÓN ESENCIAL PARA QUE LA POLICÍA NACIONAL DEL PERÚ PUEDA REQUERIR LA IDENTIFICACIÓN DE UNA PERSONA EN LA VÍA PÚBLICA SIN ORDEN JUDICIAL NI FISCAL SEGÚN EL ARTÍCULO 205 MODIFICADO POR LA LEY 32130?:', 'QUE LA POLICÍA CONSIDERE NECESARIO PREVENIR UN DELITO U OBTENER INFORMACIÓN ÚTIL PARA LA AVERIGUACIÓN DE UN HECHO PUNIBLE.', 'ART. ÚNICO art. 205', '184896'),
    (2704, 'SUB-2704', 'SBM5', 'EN RELACIÓN A LA INTERVENCIÓN POLICIAL REGULADA POR EL ARTÍCULO 205, ¿QUÉ DERECHO LE ASISTE AL CIUDADANO INTERVENIDO POR CONTROL DE IDENTIDAD?:', 'SOLICITAR LA IDENTIDAD DEL POLICÍA, LA DEPENDENCIA ASIGNADA Y SER INFORMADO QUE LA INTERVENCIÓN PUEDE SER REGISTRADA EN AUDIO Y VIDEO.', 'ART. ÚNICO art. 205', '184897'),
    (2705, 'SUB-2705', 'SBM5', '¿QUÉ ACTUACIÓN POLICIAL ADICIONAL ACTIVA LA OBLIGACIÓN DE LEVANTAR ACTA Y COMUNICACIÓN INMEDIATA Y POR ESCRITO AL MINISTERIO PÚBLICO SEGÚN EL ARTÍCULO 205 MODIFICADO?:', 'REGISTRAR LAS VESTIMENTAS, EQUIPAJE O VEHÍCULO ANTE UN FUNDADO MOTIVO QUE EL INTERVENIDO PUEDA ESTAR VINCULADO A UN UN HECHO DELICTUOSO.', 'ART. ÚNICO art. 205', '184898'),
    (2706, 'SUB-2706', 'SBM5', 'RESPECTO A LA TOMA DE FOTOGRAFÍAS DEL IMPUTADO EN EL CONTROL DE IDENTIDAD, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES ES CORRECTA CONFORME AL ARTÍCULO 205 REFORMADO?:', 'LAS FOTOGRAFIAS PUEDEN SER TOMADA CONTRA LA VOLUNTAD DEL IMPUTADO, DEBIENDO LEVANTARSE UN ACTA Y COMUNICARSE AL MINISTERIO PÚBLICO.', 'ART. ÚNICO art. 205', '184899'),
    (2707, 'SUB-2707', 'SBM5', '¿CUÁL DE LAS SIGUIENTES FUNCIONES NO SE ENCUENTRA EXPRESAMENTE HABILITADA EN EL ARTÍCULO 205, BAJO LA COMPETENCIA POLICIAL VINCULADA AL CONTROL DE IDENTIDAD?:', 'EMITIR CITACIONES JUDICIALES EN EL ACTO DE INTERVENCIÓN.', 'ART. ÚNICO art. 205', '184900'),
    (2708, 'SUB-2708', 'SBM5', 'SEGÚN LA ÚLTIMA REFORMA, ¿CUÁL ES LA CONSECUENCIA JURÍDICA SI LA INTERVENCIÓN POLICIAL EN EL CONTROL DE IDENTIDAD CULMINA CON UN HALLAZGO POSITIVO DURANTE EL REGISTRO?:', 'EL POLICÍA DEBE LEVANTAR UN ACTA, DESCRIBIR LO ENCONTRADO Y COMUNICAR INMEDIATAMENTE AL MINISTERIO PÚBLICO Y POR ESCRITO.', 'ART. ÚNICO art. 205', '184901'),
    (2709, 'SUB-2709', 'SBM5', '¿EN QUÉ CASOS ESTÁ AUTORIZADA LA TOMA DE FOTOGRAFIAS DEL IMPUTADO, SIN PERJUICIO DE SUS IMPRESIONES DIGITALES INCLUSO CONTRA DE SU VOLUNTAD, SEGÚN EL ARTÍCULO 205 MODIFICADO?:', 'SIEMPRE QUE SEA NECESARIO PARA LAS FINALIDADES DEL JUICIO O PARA LAS FINALIDADES DE IDENTIFICACION.', 'ART. ÚNICO art. 205', '184902'),
    (2710, 'SUB-2710', 'SBM5', '¿CUÁL ES EL TIEMPO LIMITE PARA LA COMUNICACIÓN AL MINISTERIO PÚBLICO, CUANDO SE REALICE EL REGISTRO PERSONAL, DE EQUIPAJE O VEHÍCULO CON RESULTADO POSITIVO DURANTE EL CONTROL DE IDENTIDAD POLICIAL?:', 'DE MANERA INMEDIATA Y POR ESCRITO CONFORME LO ESTABLECE EL ARTÍCULO 205 MODIFICADO.', 'ART. ÚNICO art. 205', '184903'),
    (2711, 'SUB-2711', 'SBM5', '¿CUÁL DE LOS SIGUIENTES ELEMENTOS DEBE CONSIGNAR OBLIGATORIAMENTE EL REQUERIMIENTO FISCAL Y, EN SU CASO, LA RESOLUCIÓN JUDICIAL QUE AUTORIZA LA INTERVENCIÓN, GRABACIÓN O REGISTRO DE COMUNICACIONES, SEGÚN EL ARTÍCULO 230 DEL D.LEG. 957 MODIFICADO POR LA LEY 32130?:', 'LA IDENTIDAD DEL TELÉFONO O MEDIO DE COMUNICACIÓN A INTERVENIR, EL NOMBRE Y DIRECCIÓN DEL AFECTADO SI SE CONOCEN, LA FORMA, EL ALCANCE Y DURACIÓN DE LA MEDIDA, ASÍ COMO LA DEPENDENCIA Y LOS DATOS DEL PERSONAL POLICIAL O FISCAL A CARGO.', 'ART. ÚNICO art. 230', '184904'),
    (2712, 'SUB-2712', 'SBM5', 'RESPECTO AL PLAZO DE INTERVENCIÓN DE LAS COMUNICACIONES SEGÚN EL ARTÍCULO 230 (MODIFICADO POR LA LEY 32130), ¿CUÁL ES LA DISPOSICIÓN EXACTA SOBRE LA DURACIÓN Y PRÓRROGA DE LA MEDIDA?:', 'EL PLAZO MÁXIMO ES DE SESENTA DÍAS, PRORROGABLE POR ÚNICA VEZ POR IGUAL PLAZO, PREVIA SUSTENTACIÓN FISCAL Y DECISIÓN MOTIVADA DEL JUEZ, SOLO SUSTENTADA EN NUEVOS Y SUFICIENTES ELEMENTOS PROBATORIOS.', 'ART. ÚNICO art. 230', '184905'),
    (2713, 'SUB-2713', 'SBM5', '¿CUÁL DE LOS SIGUIENTES MOTIVOS JUSTIFICARÍA LEGALMENTE QUE SE CONCEDA UNA PRÓRROGA A LA INTERVENCIÓN DE COMUNICACIONES, AUTORIZADA JUDICIALMENTE SEGÚN LA LEY 32130 Y EL ARTÍCULO 230 DEL D.LEG 957?:', 'LA EXISTENCIA DE NUEVOS APORTES Y SUFICIENTES ELEMENTOS PROBATORIOS QUE LA JUSTIFIQUEN.', 'ART. ÚNICO art. 230', '184906'),
    (2714, 'SUB-2714', 'SBM5', 'SEGÚN LA MODIFICACIÓN INTRODUCIDA POR LA LEY 32130 AL ARTÍCULO 261 DEL CÓDIGO PROCESAL PENAL, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES DEFINE CORRECTAMENTE LA VIGENCIA DE LA REQUISITORIA CURSADA A LA AUTORIDAD POLICIAL?:', 'LA REQUISITORIA MANTIENE SU VIGENCIA POR SEIS MESES, SALVO QUE FUESEN RENOVADAS.', 'ART. ÚNICO art. 261', '184907'),
    (2715, 'SUB-2715', 'SBM5', 'CONFORME AL ARTÍCULO 261 MODIFICADO POR LA LEY 32130, ¿EN CUÁL DE LOS SIGUIENTES SUPUESTOS LA REQUISITORIA NO CADUCA AUTOMÁTICAMENTE A LOS SEIS MESES Y SE MANTIENE VIGENTE HASTA LA EFECTIVA DETENCIÓN DEL REQUISITORIADO?:', 'DELITOS DE TERRORISMO Y DELITOS COMETIDOS POR ORGANIZACIONES CRIMINALES.', 'ART. ÚNICO art. 261', '184908'),
    (2716, 'SUB-2716', 'SBM5', '¿CUÁL ES LA OBLIGACIÓN DEL JUEZ DE LA INVESTIGACIÓN PREPARATORIA RESPECTO A LA PRISIÓN PREVENTIVA O MEDIDAS DE COMPARECENCIA RESTRICTIVAS TRANSCURRIDOS SEIS MESES DESDE SU EJECUCIÓN O DESDE LA ÚLTIMA AUDIENCIA EN LA QUE SE HUBIERA DISCUTIDO LA CESACIÓN DE LA MEDIDA?:', 'DEBERA REVISAR DE OFICIO LA VIGENCIA DE LOS PRESUPUESTOS QUE DIERON LUGAR A LA IMPOSICIÓN DE LA MEDIDA COERCITIVA.', 'ART. ÚNICO art. 283', '184909'),
    (2717, 'SUB-2717', 'SBM5', '¿BAJO QUÉ CIRCUNSTANCIAS PROCEDERÁ LA CESACIÓN DE LA PRISIÓN PREVENTIVA O DE LAS MEDIDAS DE COMPARECENCIA SEGÚN EL ARTÍCULO 83 DE LA LEY N°32130?:', 'CUANDO NUEVOS ELEMENTOS DE CONVICCIÓN DEMUESTREN QUE NO CONCURREN O NO SUBSISTEN LOS MOTIVOS QUE ORIGINARON LA MEDIDA Y RESULTE NECESARIO SUSTITUIRLA POR COMPARECENCIA.', 'ART. ÚNICO art. 283', '184910'),
    (2718, 'SUB-2718', 'SBM5', 'PARA LA DETERMINACION DE LA MEDIDA SUSTITUTIVA EL JUEZ TENDRA EN CONSIDERACION ADICIONALMENTE, SEÑALE LA CORRECTA:', 'LAS CARACTERÍSTICAS PERSONALES DEL IMPUTADO, EL TIEMPO TRANSCURRIDO DESDE LA PRIVACIÓN DE LIBERTAD Y EL ESTADO DE LA CAUSA.', 'ART. ÚNICO art. 283', '184911'),
    (2719, 'SUB-2719', 'SBM5', '¿QUÉ SUCEDE SI EL JUEZ DETERMINA LA CESACIÓN DE LA PRISIÓN PREVENTIVA Y LA REEMPLAZA POR COMPARECENCIA, SEGÚN EL TEXTO PROCESADO?:', 'EL JUEZ DEBE IMPONER MEDIDAS O REGLAS DE CONDUCTA NECESARIAS PARA GARANTIZAR LA PRESENCIA DEL IMPUTADO O EVITAR QUE SE LESIONE LA FINALIDAD DE LA MEDIDA.', 'ART. ÚNICO art. 283', '184912'),
    (2720, 'SUB-2720', 'SBM5', '¿QUÉ DERECHO LE ASISTE AL IMPUTADO RESPECTO A LA SOLICITUD DE CESACIÓN DE PRISIÓN PREVENTIVA O COMPARECENCIA RESTRICTIVA?:', 'PUEDE SOLICITAR LA CESACIÓN TANTAS VECES COMO LO CONSIDERE PERTINENTE.', 'ART. ÚNICO art. 283', '184913'),
    (2721, 'SUB-2721', 'SBM5', '¿CUÁL ES LA FINALIDAD PRINCIPAL DE LA INVESTIGACIÓN PREPARATORIA SEGÚN EL ARTÍCULO 321?:', 'REUNIR ELEMENTOS DE CONVICCIÓN PARA QUE EL FISCAL DECIDA SI FORMULA O NO ACUSACIÓN Y PERMITIR AL IMPUTADO PREPARAR SU DEFENSA. Ley 32130 - Modifica Código Procesal Penal para fortalecer la investigación del delito como función de la Policía', 'ART. ÚNICO art. 321', '184914'),
    (2722, 'SUB-2722', 'SBM5', 'RESPECTO A LA ESTRUCTURA DE LA INVESTIGACIÓN PREPARATORIA (ART 321)¿ SEÑALE CUÁL ES LA CORRECTA, SEGÚN LA MODIFICACIÓN ESTABLECIDA EN LA LEY N°32130?:', 'CONSTA DE DOS SUBETAPAS: LA INVESTIGACIÓN PRELIMINAR REALIZADA POR LA POLICIA NACIONAL DEL PERU CON DIRECCIÓN FISCAL Y LA INVESTIGACIÓN PREPARATORIA FORMALIZADA DIRIGIDA POR EL MINISTERIO PÚBLICO.', 'ART. ÚNICO art. 321', '184915'),
    (2723, 'SUB-2723', 'SBM5', 'SEGÚN EL ARTÍCULO 321 MODIFICADO, ¿QUÉ ROL CORRESPONDE A LA POLICÍA NACIONAL DEL PERÚ EN LA ETAPA PRELIMINAR DE INVESTIGACIÓN?', 'ACTÚA DIRECTAMENTE EN LA INVESTIGACIÓN PRELIMINAR BAJO LA CONDUCCIÓN JURÍDICA DEL MINISTERIO PÚBLICO.', 'ART. ÚNICO art. 321', '184916'),
    (2724, 'SUB-2724', 'SBM5', '¿CUÁL DE LOS SIGUIENTES ASPECTOS, NO ES UNA FINALIDAD DE LA INVESTIGACIÓN PREPARATORIA SEGÚN EL ART 321 DE LA LEY N°32130?:', 'EJECUTAR SANCIONES PENALES DE MANERA ANTICIPADA.', 'ART. ÚNICO art. 321', '184917'),
    (2725, 'SUB-2725', 'SBM5', '¿A QUIÉN CORRESPONDE LA DIRECCIÓN PRINCIPAL DE LA INVESTIGACIÓN PREPARATORIA FORMALIZADA, DE ACUERDO CON LA MODIFICACIÓN AL CÓDIGO PROCESAL PENAL?:', 'AL MINISTERIO PÚBLICO, CON APOYO EN LAS DILIGENCIAS DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. ÚNICO art. 321', '184918'),
    (2726, 'SUB-2726', 'SBM5', '¿EN EL MARCO DEL ARTÍCULO 322 DEL CÓDIGO PROCESAL PENAL, MODIFICADO POR LA LEY 32130, CUÁL DE LAS SIGUIENTES FUNCIONES CORRESPONDE DE MODO PRINCIPAL A LA POLICÍA NACIONAL DEL PERÚ DURANTE LA ETAPA PRELIMINAR DE LA INVESTIGACIÓN?:', 'PRACTICAR LA INVESTIGACIÓN MATERIAL DEL DELITO POR INICIATIVA PROPIA O A SOLICITUD DE PARTE, SIEMPRE QUE NO REQUIERA AUTORIZACIÓN JUDICIAL NI TENGA CONTENIDO JURISDICCIONAL.', 'ART. ÚNICO art. 322', '184919'),
    (2727, 'SUB-2727', 'SBM5', 'SEGÚN EL ARTÍCULO 322 DEL CÓDIGO PROCESAL PENAL TRAS SU MODIFICACIÓN, ¿EN QUÉ SUPUESTO EL MINISTERIO PÚBLICO PUEDE SOLICITAR EL APOYO DE LA POLICÍA NACIONAL DEL PERÚ UNA VEZ FORMALIZADA LA INVESTIGACIÓN PREPARATORIA?:', 'PARA QUE LA POLICÍA REALICE INVESTIGACIONES COMPLEMENTARIAS BAJO LA DIRECCIÓN DEL MINISTERIO PÚBLICO.', 'ART. ÚNICO art. 322', '184920'),
    (2728, 'SUB-2728', 'SBM5', 'DE ACUERDO CON EL ARTÍCULO 329, MODIFICADO POR LA LEY 32130, ¿CUÁL ES EL MODO PROCEDIMENTAL CORRECTO PARA INICIAR LOS ACTOS DE INVESTIGACIÓN POR PARTE DE LA POLICÍA NACIONAL DEL PERÚ EN UN CASO DE SOSPECHA DE DELITO?:', 'LA POLICÍA NACIONAL INICIA LOS ACTOS DE INVESTIGACIÓN COMUNICANDO DE FORMA INMEDIATA AL FISCAL CUANDO TENGA CONOCIMIENTO DE LA SOSPECHA DE LA COMISIÓN DE UN HECHO QUE REVISTE LOS CARACTERES DE DELITO, POR DENUNCIA DE LOS AGRAVIADOS, O MEDIANTE DISPOSICIÓN FISCAL.', 'ART. ÚNICO art. 329', '184922'),
    (2729, 'SUB-2729', 'SBM5', '¿CUÁL ES LA FINALIDAD INMEDIATA DE LA INVESTIGACIÓN PRELIMINAR, SEGÚN EL ARTÍCULO 330 MODIFICADO POR LA LEY 32130?:', 'REALIZAR ACTOS URGENTES O INAPLAZABLES PARA DETERMINAR LA EXISTENCIA DE LOS HECHOS, SU DELICTUOSIDAD Y ASEGURAR LOS ELEMENTOS MATERIALES, ASÍ COMO INDIVIDUALIZAR A TODOS LOS INVOLUCRADOS.', 'ART. ÚNICO art. 330', '184923'),
    (2730, 'SUB-2730', 'SBM5', '¿QUIÉN ESTÁ ENCARGADO DE LA INVESTIGACIÓN PRELIMINAR DEL DELITO, CONFORME AL ARTÍCULO 330 DE LA LEY N°32130, MARQUE LA RESPUESTA CORRECTA?:', 'LA POLICÍA NACIONAL DEL PERÚ, CON LA CONDUCCIÓN JURÍDICA DEL FISCAL.', 'ART. ÚNICO art. 330', '184924'),
    (2731, 'SUB-2731', 'SBM5', '¿CUÁL DE LOS ENUNCIADOS, NO ES UN PROPÓSITO INMEDIATO DE LA INVESTIGACIÓN PRELIMINAR, SEGÚN EL ART 330 DE LA LEY N°32130?:', 'FORMALIZAR LA ACUSACIÓN ANTE EL ÓRGANO JURISDICCIONAL COMPETENTE.', 'ART. ÚNICO art. 330', '184925'),
    (2732, 'SUB-2732', 'SBM5', 'DENTRO DEL MARCO DEL ARTÍCULO 330 REFORMADO, ¿CUÁL ES EL PAPEL DE LA POLICÍA NACIONAL AL TENER CONOCIMIENTO DE UN DELITO DE EJERCICIO PÚBLICO DE LA ACCIÓN PENAL?:', 'PODRA CONSTITUIRSE INMEDIATAMENTE EN EL LUGAR DE LOS HECHOS CON PERSONAL POLICIAL ESPECIALIZADO Y EFECTUAR UN EXAMEN PARA ESTABLECER LA REALIDAD DE LOS HECHOS.', 'ART. ÚNICO art. 330', '184926'),
    (2733, 'SUB-2733', 'SBM5', 'LA FINALIDAD MEDIATA DE LA INVESTIGACIÓN PRELIMINAR, DE CONFORMIDAD AL ART 330 DE LA LEY N°32130, ES:', 'INVESTIGAR LOS HECHOS IDENTIFICANDO,', 'ART. ÚNICO art. 330', '184927'),
    (2734, 'SUB-2734', 'SBM5', 'DENTRO DE LA INVESTIGACIÓN PRELIMINAR BAJO LA LEY 32130, ¿QUÉ ACTO ESTÁ JUSTIFICADO COMO FUNCIÓN AUTÓNOMA POLICIAL?:', 'REALIZAR ACTOS URGENTES O INAPLAZABLES NECESARIOS PARA IMPEDIR CONSECUENCIAS ULTERIORES DEL DELITO.', 'ART. ÚNICO art. 330', '184928'),
    (2735, 'SUB-2735', 'SBM5', 'AL TENER CONOCIMIENTO DE UN DELITO DE EJERCIO PUBLICO, QUIENES DEBEN CONSTITUIRSE INMEDIATAMENTE AL LUGAR DE LOS HECHOS?:', 'EL FISCAL O LA POLICIA.', 'ART. ÚNICO art. 330', '184929'),
    (2736, 'SUB-2736', 'SBM5', 'SEGÚN EL ARTÍCULO 330, ¿QUÉ FUNCIÓN CUMPLE EL INFORME POLICIAL EMITIDO AL FISCAL AL CONCLUIR LA INVESTIGACIÓN PRELIMINAR? Ley 32130 - Modifica Código Procesal Penal para fortalecer la investigación del delito como función de la Policía', 'PERMITE DECIDIR SOBRE LA FORMALIZACIÓN DE LA INVESTIGACIÓN PREPARATORIA.', 'ART. ÚNICO art. 330', '184930'),
    (2737, 'SUB-2737', 'SBM5', 'SOBRE LA FACULTAD DE CONSTITUIRSE EN EL LUGAR DE LOS HECHOS, ¿EN QUÉ CASOS PUEDEN HACERLO EL FISCAL O LA POLICÍA NACIONAL?:', 'AL TENER CONOCIMIENTO DE UN DELITO DE EJERCICIO PÚBLICO DE LA ACCIÓN PENAL.', 'ART. ÚNICO art. 330', '184931'),
    (2738, 'SUB-2738', 'SBM5', 'CONFORME AL ART 330 DE LA LEY N°32130, ¿QUÉ ELEMENTO NO ES DESTACADO COMO COMPETENCIA DE LA INVESTIGACIÓN PRELIMINAR DE LA PNP BAJO CONDUCCIÓN FISCAL?:', 'EMITIR AUTO DE PRISIÓN PREVENTIVA.', 'ART. ÚNICO art. 330', '184932'),
    (2739, 'SUB-2739', 'SBM5', 'DE ACUERDO AL ARTÍCULO 331, ¿CUÁL ES EL DEBER INMEDIATO DE LA POLICÍA NACIONAL DEL PERÚ AL TENER CONOCIMIENTO DE LA COMISIÓN DE UN DELITO?:', 'INICIAR LA INVESTIGACIÓN PRELIMINAR, COMUNICAR DE FORMA INMEDIATA AL MINISTERIO PÚBLICO, TANTO POR LA VÍA MÁS RÁPIDA COMO POR ESCRITO, INDICANDO LOS ELEMENTOS ESENCIALES DEL HECHO Y LA ACTIVIDAD CUMPLIDA.', 'ART. ÚNICO art. 331', '184933'),
    (2740, 'SUB-2740', 'SBM5', 'SEGÚN LA MODIFICACIÓN DEL ARTÍCULO 331, ¿CUÁNDO DEBE LA POLICÍA PONER A DISPOSICIÓN DEL FISCAL TODO LO ACTUADO DURANTE LA INVESTIGACIÓN PRELIMINAR?:', 'AL FINALIZAR LA INVESTIGACIÓN PRELIMINAR, MEDIANTE EL CORRESPONDIENTE INFORME POLICIAL.', 'ART. ÚNICO art. 331', '184934'),
    (2741, 'SUB-2741', 'SBM5', '¿QUÉ INFORMACIÓN ADICIONAL DEBE REMITIR LA POLICÍA AL MINISTERIO PÚBLICO, SEGÚN EL ARTÍCULO 331, SIN PERJUICIO DE LA COMUNICACIÓN INMEDIATA?:', 'TODA LA DOCUMENTACIÓN QUE PUDIERA EXISTIR RELACIONADA AL HECHO INVESTIGADO.', 'ART. ÚNICO art. 331', '184935'),
    (2742, 'SUB-2742', 'SBM5', 'RESPECTO AL INFORME POLICIAL REGULADO EN EL ARTÍCULO 332, ¿CUÁL DE LOS SIGUIENTES ENUNCIADOS ES CORRECTO EN CUANTO A SU NATURALEZA Y EFECTOS JURÍDICOS ANTE EL FISCAL?:', 'EL INFORME POLICIAL NO ES VINCULANTE.', 'ART. ÚNICO art. 332', '184936'),
    (2743, 'SUB-2743', 'SBM5', 'SEGÚN LA MODIFICACIÓN INTRODUCIDA POR LA LEY 32130 AL ARTÍCULO 332, ¿CUÁL ES LA RESPONSABILIDAD QUE ASUME LA POLICÍA NACIONAL RESPECTO DE LA PRESENTACIÓN DEL INFORME POLICIAL AL MINISTERIO PÚBLICO?:', 'RESPONSABILIDAD FUNCIONAL POR LA NO PRESENTACIÓN OPORTUNA DEL INFORME CONFORME AL PLAZO OTORGADO POR EL FISCAL.', 'ART. ÚNICO art. 332', '184937'),
    (2744, 'SUB-2744', 'SBM5', 'CONFORME A LO DISPUESTO EN EL ARTÍCULO 332, ¿CUÁLES DE LOS SIGUIENTES ELEMENTOS NO DEBE NECESARIAMENTE CONTENER EL INFORME POLICIAL REMITIDO AL FISCAL?:', 'UNA VALORACIÓN DEFINITIVA SOBRE LA CULPABILIDAD DEL INVESTIGADO.', 'ART. ÚNICO art. 332', '184938'),
    (2745, 'SUB-2745', 'SBM5', '¿CUÁL ES LA FUNCIÓN PRINCIPAL DEL INFORME POLICIAL EN EL PROCEDIMIENTO PENAL PERUANO, CONFORME AL ARTÍCULO 332 MODIFICADO POR LA LEY 32130?', 'PROPORCIONAR ANTECEDENTES, DILIGENCIAS REALIZADAS, PRECALIFICACIONES Y CONCLUSIONES PARA FUNDAMENTAR LA CONTINUACIÓN O NO DE LA INVESTIGACIÓN PREPARATORIA.', 'ART. ÚNICO art. 332', '184940'),
    (2746, 'SUB-2746', 'SBM5', 'SEGÚN EL ARTÍCULO 337, ¿EN QUÉ SUPUESTO ESPECÍFICO LA INVESTIGACIÓN PRELIMINAR PUEDE SER AMPLIADA UNA VEZ FORMALIZADA LA INVESTIGACIÓN PREPARATORIA?:', 'CUANDO EL FISCAL ADVIERTA UN GRAVE DEFECTO EN LA ACTUACIÓN DE LA DILIGENCIA O SE DEBA COMPLETAR INELUDIBLEMENTE POR LA INCORPORACIÓN DE NUEVOS ELEMENTOS DE CONVICCIÓN.', 'ART. ÚNICO art. 337', '184942'),
    (2747, 'SUB-2747', 'SBM5', '¿CUÁL ES EL LÍMITE IMPUESTO A LA POLICÍA NACIONAL POR EL ARTÍCULO 337 RESPECTO A LA REALIZACIÓN DE DILIGENCIAS INVESTIGATIVAS?', 'SOLO PUEDE REALIZAR DILIGENCIAS DISPUESTAS Y ENMARCADAS DENTRO DE LOS LÍMITES DE LA LEY, SEGÚN LO DISPONGA EL FISCAL.', 'ART. ÚNICO art. 337', '184944'),
    (2748, 'SUB-2748', 'SBM5', 'RESPECTO A LA NATURALEZA DE LA INVESTIGACIÓN PRELIMINAR EN EL MARCO DE LA LEY N°32130, CONFORME AL ARTÍCULO 337, INDIQUE LA AFIRMACIÓN CORRECTA:', 'ES UNA SUBETAPA DE LA INVESTIGACIÓN PREPARATORIA Y ESTÁ SUJETA A LIMITACIONES RELATIVAS A SU REPETICIÓN Y AMPLIACIÓN.', 'ART. ÚNICO art. 337', '184945'),
    (2749, 'SUB-2749', 'SBM5', 'CONFORME AL ARTÍCULO 337, ¿CUÁL DE LOS SIGUIENTES ENUNCIADOS REFLEJA CORRECTAMENTE LA RELACIÓN ENTRE LA ACTUACIÓN FISCAL Y POLICIAL EN LA INVESTIGACIÓN DE DELITOS?:', 'LA POLICÍA REALIZA DILIGENCIAS QUE CONSIDERE PERTINENTES Y ÚTILES, PERO SIEMPRE DENTRO DE LOS LÍMITES FIJADOS POR LA LEY Y BAJO LAS DISPOSICIONES DEL FISCAL.', 'ART. ÚNICO art. 337', '184946'),
    (2750, 'SUB-2750', 'SBM5', 'SEGÚN EL ARTÍCULO 353 MODIFICADO POR LA LEY 32130, ¿CUÁL ES LA CONDICIÓN ESENCIAL PARA QUE EL AUTO DE ENJUICIAMIENTO PUEDA SER RECURRIDO POR LAS PARTES PROCESALES?:', 'SI LA IMPUTACIÓN NECESARIA NO ESTÁ DEBIDAMENTE FORMULADA, ES DECIR, NO SE IDENTIFICAN CORRECTAMENTE LOS HECHOS Y LOS ELEMENTOS PROBATORIOS QUE TIENDEN A ACREDITARLA O LAS OBSERVACIONES ASUMIDAS EN ETAPA INTERMEDIA.', 'ART. ÚNICO art. 353', '184947'),
    (2751, 'SUB-2751', 'SBM5', '¿CUÁL ES EL ÁMBITO DE APLICACIÓN TERRITORIAL DEL DECRETO LEGISLATIVO 1611 RESPECTO A LA PREVENCIÓN E INVESTIGACIÓN DEL DELITO DE EXTORSIÓN Y SUS DELITOS CONEXOS, SEGÚN EL ARTÍCULO 2?', 'SE APLICA EN TODO EL TERRITORIO DE LA REPÚBLICA, INCLUYENDO ÁREAS DE EXCLUSIÓN, RÉGIMEN ESPECIAL ADMINISTRATIVO Y EL CIBERESPACIO, SALVO LAS EXCEPCIONES EXPRESAMENTE PREVISTAS.', 'ART. 2', '185359'),
    (2752, 'SUB-2752', 'SBM5', 'SEGÚN EL ARTÍCULO 2 DEL DECRETO LEGISLATIVO 1611, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES ES CORRECTA RESPECTO A LAS ACTUACIONES EN PROPIEDAD PRIVADA EN EL MARCO DE LA PREVENCIÓN E INVESTIGACIÓN DE EXTORSIÓN?', 'LAS ACTUACIONES EN PROPIEDAD QUE EXIGEN MANDATO JUDICIAL, Y CON LA ÚNICA EXCLUSIÓN DE RECINTOS PROTEGIDOS POR INMUNIDAD DIPLOMÁTICA.', 'ART. 2', '185360'),
    (2753, 'SUB-2753', 'SBM5', '¿CON QUÉ TIPO DE ELEMENTOS PUEDE ESTAR RELACIONADO EL ÁMBITO DE APLICACIÓN DEL DECRETO LEGISLATIVO 1611 PARA VINCULAR A PRESUNTOS AUTORES O VÍCTIMAS DE EXTORSIÓN Y DELITOS CONEXOS?', 'CON CIRCUNSTANCIAS, EFECTOS, OBJETOS, INSTRUMENTOS O MEDIOS DETECTADOS A TRAVÉS DE APARATOS, SISTEMAS O TECNOLOGÍA PARA IDENTIFICACIÓN, RASTREO, GEOPOSICIÓN, O CUALQUIER ELEMENTO MATERIAL O VIRTUAL RELEVANTE PARA LA PROBANZA DEL DELITO.', 'ART. 2', '185361'),
    (2754, 'SUB-2754', 'SBM5', 'RESPECTO AL TRATAMIENTO DEL CIBERESPACIO SEGÚN EL ARTÍCULO 2 DEL DECRETO LEGISLATIVO 1611, ¿CUÁL DE LAS SIGUIENTES OPCIONES ES CORRECTA?', 'EL CIBERESPACIO ESTÁ INCLUIDO EN EL ÁMBITO DE APLICACIÓN, PERMITIENDO LA ACTUACIÓN RESPECTO DE ELEMENTOS VIRTUALES VINCULADOS A LA EXTORSIÓN, SALVO EXCLUSION DE RECINTOS PROTEGIDOS POR INMUNIDAD DIPLOMÁTICA.', 'ART. 2 Decreto Leg. 1611 - Medidas especiales para la prev. e invest. del delito de extorsión y delitos conexos', '185362'),
    (2755, 'SUB-2755', 'SBM5', 'SEGÚN EL ARTÍCULO 2, ¿CUÁL DE LAS SIGUIENTES ALTERNATIVAS EXPRESA CORRECTAMENTE UNA EXCEPCIÓN AL ÁMBITO DE APLICACIÓN DEL DECRETO LEGISLATIVO 1611?', 'RECINTOS PROTEGIDOS POR INMUNIDAD DIPLOMÁTICA, EN CUYO CASO NO PROCEDE LA APLICACIÓN DEL DECRETO.', 'ART. 2', '185363'),
    (2756, 'SUB-2756', 'SBM5', 'SEGÚN EL ARTÍCULO 3 DEL D. LEG 1611, ¿CUÁL ES EL ROL ESPECÍFICO QUE ASUME EL MINISTERIO PÚBLICO RESPECTO A LA INVESTIGACIÓN DEL DELITO DE EXTORSIÓN Y DELITOS CONEXOS?', 'ASUME LA CONDUCCIÓN Y CONTROL JURÍDICO DE LA INVESTIGACIÓN DESDE SU INICIO.', 'ART. 3', '185364'),
    (2757, 'SUB-2757', 'SBM5', 'DE ACUERDO AL TEXTO ANALIZADO, ¿QUÉ FUNCIÓN CUMPLE LA POLICÍA NACIONAL DEL PERÚ RESPECTO AL DELITO DE EXTORSIÓN Y SUS DELITOS CONEXOS?', 'PREVIENE, INVESTIGA Y COMBATE LA DELINCUENCIA EN GENERAL, Y REALIZA LA INVESTIGACIÓN DEL DELITO DE EXTORSIÓN EN MATERIA PROCESAL PENAL.', 'ART. 3', '185365'),
    (2758, 'SUB-2758', 'SBM5', '¿CUÁL ES EL DEBER DE LAS INSTITUCIONES O PERSONAS JURÍDICAS RELACIONADAS CON LOS SERVICIOS PÚBLICOS SEGÚN EL ARTÍCULO 3 DEL D. LEG 1611?', 'COLABORAN EN LA PROVISIÓN DE DOCUMENTOS, DATOS O INFORMACIONES RELEVANTES PARA LA PREVENCIÓN E INVESTIGACIÓN DE EXTORSIÓN Y DELITOS CONEXOS.', 'ART. 3', '185366'),
    (2759, 'SUB-2759', 'SBM5', 'IDENTIFIQUE LA AFIRMACIÓN INCORRECTA EN RELACIÓN AL ARTÍCULO 3 DEL D. LEG 1611:', 'LA POLICÍA NACIONAL PUEDE INICIAR Y CONDUCIR INVESTIGACIONES DE EXTORSIÓN DE MANERA AUTÓNOMA, SIN CONTROL DEL MINISTERIO PÚBLICO.', 'ART. 3', '185367'),
    (2760, 'SUB-2760', 'SBM5', '¿CUÁL DE LAS SIGUIENTES ACCIONES DE LA POLICÍA NACIONAL DEL PERÚ ESTÁ ESPECÍFICAMENTE ORIENTADA A LA PREVENCIÓN DE LA DELINCUENCIA EN ZONAS DE ALTO RIESGO, SEGÚN EL ARTÍCULO 4 DEL D.LEG 1611?', 'RONDAS O PATRULLAJES VEHICULARES, VIGILANCIA FIJA O MÓVIL DETERMINADA POR LA POLICÍA NACIONAL DEL PERÚ', 'ART. 4', '185368'),
    (2761, 'SUB-2761', 'SBM5', 'EN EL CONTEXTO DEL D.LEG 1611, ¿CUÁL DE LAS SIGUIENTES CIRCUNSTANCIAS HABILITA EXPRESAMENTE A LA POLICÍA NACIONAL PARA REALIZAR REGISTRO PERSONAL Y VEHICULAR EN OPERATIVOS DE CONTROL TERRITORIAL?', 'CUANDO SE UTILICE MOTOCICLETA LINEAL CON DOS O MÁS OCUPANTES A BORDO', 'ART. 4', '185369'),
    (2762, 'SUB-2762', 'SBM5', 'SEGÚN EL MARCO DEL ARTÍCULO 4 DEL D.LEG 1611, SI DURANTE UN CONTROL TERRITORIAL UN INDIVIDUO NO LOGRA ACREDITAR SU IDENTIDAD A PESAR DE LAS FACILIDADES BRINDADAS, ¿CUÁL ES EL SIGUIENTE PASO QUE LA POLICÍA PUEDE TOMAR?', 'CONDUCIRLO A LA DEPENDENCIA POLICIAL PARA EFECTOS DE IDENTIFICACIÓN Y VERIFICACIÓN DE REQUISITORIAS', 'ART. 4', '185370'),
    (2763, 'SUB-2763', 'SBM5', '¿CUÁL ES EL TRATAMIENTO PROCESAL QUE OTORGA EL D.LEG 1611 A LOS CASOS EN LOS QUE DURANTE UN CONTROL SE DETECTA LA PRESENCIA DE DROGAS, ARMAS, DINERO U OBJETOS DE ORIGEN O DESTINO ILEGAL?', 'LA ACTUACIÓN POLICIAL PROSIGUE EN EL MARCO PROCESAL PENAL CORRESPONDIENTE', 'ART. 4', '185371'),
    (2764, 'SUB-2764', 'SBM5', '¿QUÉ DISPOSICIÓN ESPECÍFICA ESTABLECE EL ARTÍCULO 4 DEL D.LEG 1611 RESPECTO AL REGISTRO DE LA INFORMACIÓN PERSONAL Y TOMA DE MUESTRAS PARA IDENTIFICAR A UNA PERSONA NO IDENTIFICADA DURANTE UNA INTERVENCIÓN?', 'SE REALIZA EL REGISTRO DE INFORMACIÓN PROPORCIONADA, IMPRESIONES DECADACTILARES, CARACTERÍSTICAS FÍSICAS, SEÑAS, FOTOGRAFÍAS FACIALES Y, SI ES POSIBLE, MUESTRA DE VOZ, PREVIA INFORMACIÓN AL INTERVENIDO', 'ART. 4', '185372'),
    (2765, 'SUB-2765', 'SBM5', 'EN RELACIÓN AL PATRULLAJE EN EL CIBERESPACIO PRESCRITO EN EL ARTÍCULO 4 DEL D.LEG 1611, ¿CUÁL ES EL ALCANCE PERMITIDO PARA LA POLICÍA NACIONAL DEL PERÚ?', 'UTILIZAR INSTRUMENTOS INFORMÁTICOS EN LÍNEA Y EN TIEMPO REAL, DENTRO DEL MARCO LEGAL, PARA ALERTAR Y NEUTRALIZAR CIBERDELINCUENCIA', 'ART. 4', '185373'),
    (2766, 'SUB-2766', 'SBM5', '¿CÓMO DEBE PROCEDER LA POLICÍA NACIONAL DEL PERÚ EN CASO DE COMPROBAR UNA TASA DE ALCOHOLEMIA POSITIVA DURANTE UN OPERATIVO CONFORME AL ARTÍCULO 4 DEL D.LEG 1611?', 'CONTINUAR LA ACTUACIÓN EN EL MARCO DEL PROCESO PENAL SI LA EBRIEDAD TIPIFICA UN DELITO DE PELIGRO COMÚN', 'ART. 4', '185374'),
    (2767, 'SUB-2767', 'SBM5', '¿QUÉ REQUISITOS ESTABLECE EL ARTÍCULO 4 DEL D.LEG 1611 PARA LA TOMA DE MUESTRAS DE VOZ DE INVESTIGADOS POR PRESUNTO DELITO DE EXTORSIÓN O CONEXOS?', 'DEBE REALIZARSE EN EL MARCO CONSTITUCIONAL Y CONFORME AL PROCEDIMIENTO REGLAMENTARIO DE LA DIRECCIÓN DE CRIMINALÍSTICA', 'ART. 4', '185375'),
    (2768, 'SUB-2768', 'SBM5', 'EN CUANTO AL PLAZO DE RETENCIÓN POR CONTROL DE IDENTIDAD EN PREVENCIÓN DEL DELITO, ¿QUÉ DIRECTRIZ SEÑALA EL ARTÍCULO 4 DEL D.LEG 1611?', 'NO PUEDE EXCEDER EL TIEMPO RAZONABLE PARA SUPERAR LA FALTA DE IDENTIFICACIÓN, EQUIVALENTE AL PREVISTO EN EL CÓDIGO PROCESAL PENAL', 'ART. 4', '185376'),
    (2769, 'SUB-2769', 'SBM5', '¿QUÉ ALTERNATIVA RESUME ADECUADAMENTE LA FINALIDAD PRINCIPAL DE LAS ACCIONES PREVENTIVAS POLICIALES PREVISTAS EN EL ARTÍCULO 4 DEL D.LEG 1611 RESPECTO A LA DELINCUENCIA Y, EN PARTICULAR, LA EXTORSIÓN Y DELITOS CONEXOS?', 'PREVENIR LA COMISIÓN DE DELITOS Y GARANTIZAR LA PAZ Y SEGURIDAD HUMANA EN ZONAS DE ALTO RIESGO', 'ART. 4', '185377'),
    (2770, 'SUB-2770', 'SBM5', 'SEGÚN EL ARTÍCULO 5 DEL D.LEG 1611, ¿A TRAVÉS DE CUÁLES MEDIOS PUEDE LA POLICÍA NACIONAL DEL PERÚ RECIBIR LA NOTICIA CRIMINAL RESPECTO AL DELITO DE EXTORSIÓN Y SUS DELITOS CONEXOS?', 'POR DENUNCIA DE LA VÍCTIMA, COMUNICACIÓN DE AUTORIDAD, MEDIOS DE COMUNICACIÓN, ACCIÓN POPULAR, O INFORMACIÓN DE FUENTE CLASIFICADA, ABIERTA, IDENTIFICADA O ANÓNIMA.', 'ART. 5', '185378'),
    (2771, 'SUB-2771', 'SBM5', 'OBSERVE LAS OBLIGACIONES ESTABLECIDAS EN EL ARTÍCULO 5 DEL D.LEG 1611. SI LA POLICÍA NACIONAL DEL PERÚ TOMA CONOCIMIENTO DE UN DELITO DE EXTORSIÓN A TRAVÉS DE UNA FUENTE ANÓNIMA Y TRAS VERIFICAR LA NOTICIA, ¿QUÉ ACTUACIÓN LE CORRESPONDE REALIZAR SEGÚN DICHA NORMA?', 'COMUNICAR POR LOS MEDIOS IDÓNEOS Y CÉLERES AL MINISTERIO PÚBLICO PARA LA CONDUCCIÓN DE LA INVESTIGACIÓN.', 'ART. 5', '185379'),
    (2772, 'SUB-2772', 'SBM5', 'SOBRE EL CONCEPTO DE NOTICIA CRIMINAL REFERIDO EN EL ARTÍCULO 5 DEL D.LEG 1611, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES ES CORRECTA RESPECTO A LA PROCEDENCIA Y TRATAMIENTO DE DICHA NOTICIA?', 'CUALQUIER FUENTE, SEA ANÓNIMA O CLASIFICADA, COMPROBADA ÉSTA, POR LA UNIDAD DE INVESTIGACIÓN POLICIAL COMPETENTE, LA PONE EN CONOCIMIENTO POR LOS MEDIOS IDÓNIOS, AL MINISTERIO PÚBLICO.', 'ART. 5', '185380'),
    (2773, 'SUB-2773', 'SBM5', '¿SEGÚN EL ARTÍCULO 6 DEL D.LEG 1611, CUÁL ES LA FINALIDAD PRINCIPAL DE LAS DILIGENCIAS URGENTES E IMPRESCINDIBLES REALIZADAS POR LA UNIDAD DE INVESTIGACIÓN POLICIAL EN EL MARCO DE UN DELITO DE EXTORSIÓN Y DELITOS CONEXOS?', 'EVITAR LA PERMANENCIA DEL DELITO O LA PROLONGACIÓN DE SUS EFECTOS LESIVOS Y POSIBILITAR LA IDENTIFICACIÓN O LOCALIZACIÓN DE AUTORES, PARTÍCIPES, VÍCTIMAS, Y ELEMENTOS DE CONVICCIÓN. Decreto Leg. 1611 - Medidas especiales para la prev. e invest. del delito de extorsión y delitos conexos', 'ART. 6', '185381'),
    (2774, 'SUB-2774', 'SBM5', 'EN CASO DE RECOLECCIÓN DE REGISTROS DE VIDEOVIGILANCIA DURANTE LA INSPECCIÓN, ¿CÓMO DEBE PROCEDER LA POLICÍA DE ACUERDO AL TEXTO ANALIZADO?', 'PROCEDER A LA SOLICITUD Y RECEPCIÓN DOCUMENTADA, PARA SU RESPECTIVA VISUALIZACIÓN.', 'ART. 6', '185382'),
    (2775, 'SUB-2775', 'SBM5', 'LAS ACTAS RELATIVAS A LAS DILIGENCIAS EFECTUADAS EN EL LUGAR DE LOS HECHOS, SEGÚN EL ARTÍCULO 6, DEBEN SER LEVANTADAS:', 'DE MANERA CRONOLÓGICA Y COHERENTE, FIRMADAS EN EL MISMO LUGAR DE LOS HECHOS SALVO IMPEDIMENTO DEBIDAMENTE ACREDITADO Y FUNDAMENTADO.', 'ART. 6', '185383'),
    (2776, 'SUB-2776', 'SBM5', '¿QUÉ REQUISITO DEBEN CUMPLIR LAS VERSIONES EXPUSTAS POR LOS INTERVENIDOS PARA QUE MOTIVEN DILIGENCIAS INMEDIATAS DE CORROBORACIÓN?', 'HABER SIDO PRESTADAS LIBREMENTE, EN ESTADO NORMAL DE LAS FACULTADES PSÍQUICAS, Y HABIENDO SIDO ADVERTIDO EL DERECHO A GUARDAR SILENCIO.', 'ART. 6', '185384'),
    (2777, 'SUB-2777', 'SBM5', '¿QUÉ SUCEDE SI LAS DILIGENCIAS DE CORROBORACIÓN A LAS VERSIONES ESPONTÁNEAS RESULTAN POSITIVAS, SEGÚN LO EXPUESTO EN EL D.LEG 1611?', 'EL FISCAL PUEDE VALORAR ESTAS DILIGENCIAS PARA EFECTOS DE UNA POSIBLE CONFESIÓN SINCERA Y APLICACIÓN DE BENEFICIOS DE DISMINUCIÓN PRUDENCIAL DE LA PENA.', 'ART. 6', '185385'),
    (2778, 'SUB-2778', 'SBM5', '¿QUÉ DILIGENCIA URGENTE NO ESTÁ CONTEMPLADA EXPRESAMENTE EN EL ARTÍCULO 6 DEL D.LEG 1611?', 'LA DESTRUCCIÓN INMEDIATA DE ELEMENTOS PROBATORIOS IRRELEVANTES.', 'ART. 6', '185386'),
    (2779, 'SUB-2779', 'SBM5', '¿CUÁL DE LAS SIGUIENTES AFIRMACIONES REFLEJA ADECUADAMENTE EL SENTIDO DE LA PERENNIZACIÓN DE LA ESCENA DE LOS HECHOS A TRAÉS DE MEDIOS DE SOPORTE FISICO O DIGITAL SEGÚN EL ARTÍCULO 6?', 'INSPECCIÓN TÉCNICA POLICIAL. LEVANTAMIENTO Y RECOJO DE MUESTRAS E INDICIOS APROVECHABLES QUE CORRESPONDAN.', 'ART. 6', '185387'),
    (2780, 'SUB-2780', 'SBM5', '¿EL LEVANTAMIENTO DE LAS ACTAS EN FORMA CRONOLOGICAS Y DE MANERA COHERENTE, SUSCRIBIENDOLA QUIENES PARTICIPARON EN LAS RESPECTIVAS DILIGENCIAS, EN EL MISMO LUGAR DE LOS HECHOS SALVO IMPEDIMENTO DEBIDAMENTE ACREDITADO Y EXPRESADO?', 'SI POR RAZONES DE SEGURIDAD O CAUSAS AJENAS A LA VOLUNTAD DEL PERSONAL POLICIAL, NO ES POSIBLE LEVANTAR LAS ACTAS EN EL LUGAR DE LOS HECHOS.', 'ART. 6', '185389'),
    (2781, 'SUB-2781', 'SBM5', '¿CUÁL ES LA COMPETENCIA DE LA POLICÍA EN LAS PESQUISAS E INDAGACIONES URGENTES, CONFORME EL ARTÍCULO 6?', 'LLEVAR A CABO PESQUISAS PARA IDENTIFICAR Y LOCALIZAR AUTORES, VÍCTIMAS, MEDIOS E INSTRUMENTOS DEL DELITO, ASÍ COMO OTROS ELEMENTOS DE CONVICCIÓN.', 'ART. 6', '185390'),
    (2782, 'SUB-2782', 'SBM5', '¿CUÁL DE LOS SIGUIENTES MÉTODOS UTILIZADOS PARA LA IDENTIFICACIÓN DE PRESUNTOS AUTORES Y PARTÍCIPES DE DELITOS DE EXTORSIÓN Y CONEXOS ES EXPRESAMENTE MENCIONADO EN EL ARTÍCULO 7 DEL D.LEG 1611?', 'EXÁMENES PERICIALES PAPILOSCÓPICOS, MORFOLÓGICOS, FACIALES, CINÉTICOS (GAIT), BIOMÉTRICOS O ANTROPOMÉTRICOS.', 'ART. 7', '185391'),
    (2783, 'SUB-2783', 'SBM5', 'SEGÚN EL ARTÍCULO 7 DEL D. LEG. 1611, ¿QUÉ TECNOLOGÍA PUEDE SER EMPLEADA PARA LA UBICACIÓN DE LOS PRESUNTOS AUTORES O PARTÍCIPES DE DELITOS DE EXTORSIÓN Y CONEXOS?', 'APLICATIVOS INFORMÁTICOS PARA RASTREO O SEGUIMIENTO EN INTERNET, REDES SOCIALES U OTRAS PLATAFORMAS.', 'ART. 7', '185392'),
    (2784, 'SUB-2784', 'SBM5', '¿QUIÉNES ESTÁN OBLIGADOS A OTORGAR PRIORIDAD AL REQUERIMIENTO DE LOCALIZACIÓN Y GEOLOCALIZACIÓN EN LAS INVESTIGACIONES DE EXTORSIÓN Y DELITOS CONEXOS, SEGÚN EL ARTÍCULO 7?', 'LAS AUTORIDADES POLICIALES, FISCALES Y JUDICIALES, ASÍ COMO LOS CONCESIONARIOS DE SERVICIOS PÚBLICOS DE TELECOMUNICACIONES.', 'ART. 7', '185393'),
    (2785, 'SUB-2785', 'SBM5', 'EN VIRTUD DEL ARTÍCULO 7 DEL D. LEG. 1611, ¿QUÉ ROL CUMPLE LA INTELIGENCIA ARTIFICIAL EN LA IDENTIFICACIÓN DE PARTÍCIPES DE DELITOS DE EXTORSIÓN?', 'PUEDE UTILIZARSE COMO FORMA IDÓNEA DE COMPROBACIÓN JUNTO A OTROS EXÁMENES ESPECIALIZADOS.', 'ART. 7', '185394'),
    (2786, 'SUB-2786', 'SBM5', 'SEGÚN EL TEXTO DEL ARTÍCULO 7, ¿QUÉ ELEMENTO ES OBJETO DE LOCALIZACIÓN O UBICACIÓN MEDIANTE MEDIOS TECNOLÓGICOS EN PROCESOS DE EXTORSIÓN Y DELITOS CONEXOS?', 'PRESUNTOS AUTORES O PARTÍCIPES, VÍCTIMAS E INSTRUMENTOS, MEDIOS, EFECTOS U OBJETO MATERIAL DEL DELITO.', 'ART. 7', '185395'),
    (2787, 'SUB-2787', 'SBM5', '¿QUÉ DISPOSICIONES ADICIONALES MENCIONA EL ARTÍCULO 7 EN RELACIÓN A LOS CONCESIONARIOS DE LOS SERVICIOS PÚBLICOS DE TELECOMUNICACIONES?', 'OTORGAN PRIORIDAD AL REQUERIMIENTO CONFORME AL D. LEG. 1182, NORMAS MODIFICATORIAS Y REGLAMENTARIAS.', 'ART. 7', '185396'),
    (2788, 'SUB-2788', 'SBM5', '¿EN CUÁL DE LOS SIGUIENTES SUPUESTOS LAS ENTIDADES PÚBLICAS Y PRIVADAS ESTÁN OBLIGADAS A COOPERAR CON LA AUTORIDAD POLICIAL EN INVESTIGACIONES SOBRE EXTORSIÓN, SEGÚN EL ARTÍCULO 9 DEL D. LEG. 1611?', 'ÚNICAMENTE CUANDO EXISTA FLAGRANCIA DELICTIVA RELACIONADA CON EXTORSIÓN O DELITOS CONEXOS.', 'ART. 9', '185400'),
    (2789, 'SUB-2789', 'SBM5', '¿QUÉ PROCEDIMIENTO DEBE OBSERVARSE PARA OBTENER INFORMACIÓN DE ABONADOS DE TELEFONÍA MÓVIL UTILIZADOS EN LA COMISIÓN DE DELITOS DE EXTORSIÓN SEGÚN EL CITADO ARTÍCULO?', 'LA INFORMACIÓN SE PROPORCIONA MEDIANTE UN PROCEDIMIENTO DEBIDAMENTE ESTABLECIDO EN EL CÓDIGO PROCESAL PENAL.', 'ART. 9', '185401'),
    (2790, 'SUB-2790', 'SBM5', '¿CUÁL DE LAS SIGUIENTES ENTIDADES NO SE MENCIONA EXPRESAMENTE EN EL ARTÍCULO 9 COMO HABILITADA PARA INTEGRAR EL MECANISMO PÚBLICO-PRIVADO DE INTERCAMBIO DE INFORMACIÓN?', 'MINISTERIO DE JUSTICIA Y DERECHOS HUMANOS.', 'ART. 9', '185403'),
    (2791, 'SUB-2791', 'SBM5', 'EN EL CONTEXTO DEL ARTÍCULO 9, ¿QUIÉN PUEDE ARTICULAR Y ESTABLECER PROCEDIMIENTOS PARA EL FUNCIONAMIENTO DEL MECANISMO PÚBLICO-PRIVADO PARA EL INTERCAMBIO DE INFORMACIÓN?', 'LA UNIDAD DE INTELIGENCIA FINANCIERA DEL PERÚ (UIF-PERÚ)', 'ART. 9', '185405'),
    (2792, 'SUB-2792', 'SBM5', '¿A QUÉ DEBER ESTÁN SUJETOS LOS PARTICIPANTES, REPRESENTANTES Y PERSONAL DE ENTIDADES QUE TOMAN CONOCIMIENTO DE INFORMACIÓN INTERCAMBIADA EN EL MECANISMO PÚBLICO-PRIVADO?', 'DEBER DE RESERVA DE INFORMACIÓN CONFORME AL ARTÍCULO 12 DE LA LEY N° 27693.', 'ART. 9', '185406'),
    (2793, 'SUB-2793', 'SBM5', '¿CUÁL ES EL ROL DE LA UIF-PERÚ RESPECTO AL MECANISMO PÚBLICO-PRIVADO DE LUCHA CONTRA LA EXTORSIÓN Y DELITOS CONEXOS SEGÚN EL ARTÍCULO 9?', 'EJERCER LA ARTICULACIÓN DEL MECANISMO Y ESTABLECER MEDIANTE RESOLUCIÓN LOS ALCANCES Y PROCEDIMIENTOS.', 'ART. 9', '185407'),
    (2794, 'SUB-2794', 'SBM5', 'SEGÚN EL ARTÍCULO 9, ¿CUÁLES SUJETOS PRIVADOS PUEDEN INTEGRARSE AL MECANISMO PÚBLICO- PRIVADO DE INTERCAMBIO DE INFORMACIÓN? Decreto Leg. 1611 - Medidas especiales para la prev. e invest. del delito de extorsión y delitos conexos', 'LOS SUJETOS OBLIGADOS A INFORMAR A LA UIF-PERÚ EN MATERIA DE PREVENCIÓN DEL LAVADO DE ACTIVOS Y FINANCIAMIENTO DEL TERRORISMO.', 'ART. 9', '185409'),
    (2795, 'SUB-2795', 'SBM5', '¿CUÁL ES LA FUNCIÓN PRINCIPAL DE LA POLICÍA NACIONAL DEL PERÚ EN LA INVESTIGACIÓN DEL DELITO DE EXTORSIÓN Y SUS DELITOS CONEXOS SEGÚN EL ARTÍCULO 10 DEL D.LEG 1611?', 'RECOMENDAR LA ESTRATEGIA DE LA INVESTIGACIÓN AL FISCAL Y EJECUTAR ACCIONES TÉCNICAS NECESARIAS BAJO CONDUCCIÓN FISCAL.', 'ART. 10', '185410'),
    (2796, 'SUB-2796', 'SBM5', 'FRENTE A LA INCAUTACIÓN DE VEHÍCULOS O BIENES INMUEBLES VINCULADOS A DELITOS DE EXTORSIÓN Y CONEXOS, ¿QUÉ PROCEDIMIENTO SE DEBE SEGUIR SEGÚN EL ARTÍCULO 10?', 'LA INCAUTACIÓN DEBE SER CONFIRMADA POR UN JUEZ A SOLICITUD DEL FISCAL EN UN PLAZO DE 48 HORAS DESDE LA INCAUTACIÓN.', 'ART. 10', '185411'),
    (2797, 'SUB-2797', 'SBM5', 'DE ACUERDO CON EL ARTÍCULO 10 DEL D.LEG 1611, ¿QUÉ LÍMITE IMPONE LA ENTREGA DE INFORMACIÓN POR PARTE DE ENTIDADES PÚBLICAS O PRIVADAS REQUERIDAS POR LA POLICÍA NACIONAL DEL PERÚ?', 'QUE LA INFORMACIÓN REQUERIDA EXCLUYA LO REFERENTE AL SECRETO BANCARIO, LA RESERVA TRIBUTARIA, EL SECRETO DE LAS COMUNICACIONES Y LA PROTECCIÓN DE DATOS PERSONALES.', 'ART. 10', '185414'),
    (2798, 'SUB-2798', 'SBM5', 'RESPECTO A LOS BIENES INCAUTADOS POR LA POLICÍA NACIONAL DEL PERÚ, ¿QUÉ CARACTERÍSTICA DEBEN CUMPLIR PARA SER INCAUTADOS SEGÚN EL ARTÍCULO 10 DEL D.LEG 1611?', 'PUEDEN SER INCAUTADOS SI SE DUDA DE LA LEGALIDAD DE SU ORIGEN Y SE ENCUENTRAN VINCULADOS A DELITOS INVESTIGADOS.', 'ART. 10', '185416'),
    (2799, 'SUB-2799', 'SBM5', '¿QUÉ ACCIÓN PUEDE TOMAR LA POLICÍA NACIONAL DEL PERÚ RESPECTO A CENTROS DE OPERACIONES ILÍCITAS CONFORME AL ARTÍCULO 10 DEL D.LEG 1611?', 'EJECUTAR VIGILANCIA Y SEGUIMIENTO PARA IDENTIFICACIÓN, INDIVIDUALIZACIÓN Y DOCUMENTACIÓN DE LAS ACTIVIDADES CRIMINALES.', 'ART. 10', '185417'),
    (2800, 'SUB-2800', 'SBM5', 'CUANDO LA POLICÍA REQUIERE INFORMACIÓN DE REGISTROS OFICIALES O PRIVADOS DURANTE LA INVESTIGACIÓN, ¿CUÁL ES EL PROCEDIMIENTO CORRECTO SEGÚN EL ARTÍCULO 10 DEL D.LEG 1611?', 'LOS REQUERIDOS DEBEN SUMINISTRAR DATOS SIN DILACIÓN A TRAVÉS DE SOPORTES MAGNÉTICOS O ELECTRÓNICOS, SALVO EXCEPCIONES LEGALES.', 'ART. 10', '185419')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

