INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 2801 a 2900
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (2801, 'SUB-2801', 'SBM5', 'EL NIVEL DE FUERZA A EMPLEAR ES UNO DE LOS ASPECTOS IMPORTANTES QUE SE TIENEN QUE TENER EN CUENTA EN LAS TECNICAS DE INTERVENCION, Y SE REFIERE A:', 'LUEGO DE UNA APRECIACIÓN DE LA SITUACIÓN Y LAS CIRCUNSTANCIAS QUE SE PRESENTAN EN LA INTERVENCIÓN, EL EFECTIVO POLICIAL EMPLEARÁ LA FUERZA, DE ACUERDO AL NIVEL DE RESISTENCIA DE LA PERSONA A INTERVENIR.', '2DA PARTE [CAPÍTULO III] - B.1.c', '185988'),
    (2802, 'SUB-2802', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- SE HAN CONSIDERADO DOS SITUACIONES QUE SE PRESENTAN EN FORMA COTIDIANA EN EL SERVICIO POLICIAL: LA PRIMERA, CON FINES DE IDENTIFICACIÓN, Y LA SEGUNDA, CUANDO SE TRATE DE UN PRESUNTO INFRACTOR. SIN EMBARGO ...:', 'UNA NO ES EXCLUYENTE DE LA OTRA', '2DA PARTE [CAPÍTULO III] - B.2', '185989'),
    (2803, 'SUB-2803', 'SBM5', 'LA PERCEPCIÓN DEL RIESGO ES UNO DE LOS ASPECTOS IMPORTANTES QUE SE TIENEN QUE TENER EN CUENTA EN LAS TÉCNICAS DE INTERVENCIÓN, DONDE SE DEBE CONSIDERAR LAS CARACTERÍSTICAS DEL LUGAR DE LA INTERVENCIÓN (UBICACIÓN, ESTRUCTURAS DESCONOCIDAS, CALLEJONES, EDIFICACIONES, ILUMINACIÓN, ENTRE OTROS) QUE PUEDAN REPRESENTAR UN RIESGO PARA LA INTEGRIDAD DEL PERSONAL POLICIAL O DE TERCEROS, ASÍ COMO EL POSIBLE....:', 'APOYO DE OTRAS PERSONAS AL INFRACTOR', '2DA PARTE [CAPÍTULO III] - B.1.b', '185990'),
    (2804, 'SUB-2804', 'SBM5', 'EL NIVEL DE FUERZA A EMPLEAR ES UNO DE LOS ASPECTOS IMPORTANTES QUE SE TIENEN QUE TENER EN CUENTA EN LAS TECNICAS DE INTERVENCION, EN LA CUAL, LUEGO DE UNA APRECIACIÓN DE LA SITUACIÓN Y LAS CIRCUNSTANCIAS QUE SE PRESENTAN EN LA INTERVENCIÓN, EL PERSONAL POLICIAL EMPLEARÁ LA FUERZA, DE ACUERDO.....:', 'AL NIVEL DE RESISTENCIA DE LA PERSONA A INTERVENIR.', '2DA PARTE [CAPÍTULO III] - B.1.c', '185991'),
    (2805, 'SUB-2805', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- RESPECTO A LA INTERVENCIÓN CON FINES DE IDENTIFICACIÓN, ES CONVENIENTE TENER EN CONSIDERACIÓN LOS SIGUIENTES ASPECTOS:', 'IDENTIFICARSE (SALUDO, GRADO, APELLIDOS, UNIDAD EN LA QUE PRESTA SERVICIO), HACIÉNDOLE CONOCER EL MOTIVO DE LA INTERVENCIÓN.', '2DA PARTE [CAPÍTULO III] - B.2.a', '185992'),
    (2806, 'SUB-2806', 'SBM5', '¿QUÉ ASPECTOS IMPORTANTES SE TIENEN QUE TENER EN CUENTA EN LAS TÉCNICAS DE INTERVENCIÓN?', 'EL NIVEL DE FUERZA A EMPLEAR', '2DA PARTE [CAPÍTULO III] - B.1.c', '185993'),
    (2807, 'SUB-2807', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- INDIQUE LA ALTERNATIVA QUE FORMA PARTE DE LOS PASOS QUE SE DEBEN TENER EN CUENTA AL MOMENTO DE UNA INTERVENCIÓN A UN PRESUNTO INFRACTOR:', 'HACERLE SABER EL MOTIVO DE LA INTERVENCIÓN, POR EJEMPLO: ES USTED SOSPECHOSO DE ........ ; O HA COMETIDO EL DELITO DE ..........;', '2DA PARTE [CAPÍTULO III] - B.2.b', '185994'),
    (2808, 'SUB-2808', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- RESPECTO A LA INTERVENCIÓN A UN PRESUNTO INFRACTOR, INDIQUE EL ENUNCIADO CORRECTO:', 'ESTAS INTERVENCIONES SON LAS QUE REPRESENTAN UN MAYOR NIVEL DE RIESGO PARA EL PERSONAL POLICIAL. PUEDEN PRESENTARSE DURANTE EL PATRULLAJE O A MÉRITO DE UNA COMUNICACIÓN RADIAL O TELEFÓNICA DE LA UNIDAD POLICIAL. EN ESE SENTIDO, ES DE SUMA IMPORTANCIA QUE LA INFORMACIÓN QUE RECABE EL PERSONAL POLICIAL QUE VA A INTERVENIR SEA DETALLADA CON LA FINALIDAD DE TOMAR CONOCIMIENTO DE LA SITUACIÓN.', '2DA PARTE [CAPÍTULO III] - B.2.b', '185995'),
    (2809, 'SUB-2809', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- RESPECTO A LA INTERVENCIÓN A UN PRESUNTO INFRACTOR, INDIQUE EL ENUNCIADO CORRECTO. Derechos Humanos aplicados a la Función Policial - 2da parte', 'ESTA INTERVENCION SON LA QUE REPRESENTA UN MAYOR NIVEL DE RIESGO PARA EL PERSONAL POLICIAL.', '2DA PARTE [CAPÍTULO III] - B.2.b', '185996'),
    (2810, 'SUB-2810', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- INDIQUE LA ALTERNATIVA QUE NO FORMA PARTE DE LOS PASOS QUE SE DEBEN TENER EN CUENTA AL MOMENTO DE UNA INTERVENCIÓN A UN PRESUNTO INFRACTOR:', 'CULMINADA LA INTERVENCIÓN SIN NOVEDAD, EL POLICÍA DE CONTACTO (P1) AGRADECERÁ SU COLABORACIÓN, DESPLAZÁNDOSE LUEGO HACIA LA', '2DA PARTE [CAPÍTULO III] - B.2.a', '185997'),
    (2811, 'SUB-2811', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- COMPLETE CORRECTAMENTE RESPECTO A LA INTERVENCIÓN A UN PRESUNTO INFRACTOR: UNA ACCIÓN QUE AYUDARÁ A MINIMIZAR LOS RIESGOS ES (. ................... ). ELLO NOS PERMITIRÁ UBICAR CUALQUIER TIPO DE AMENAZA (ARMA U OBJETO). ESTA ACCIÓN SE EFECTÚA EN EL MOMENTO QUE EL INTERVENIDO SE ENCUENTRA FRENTE AL EFECTIVO POLICIAL QUE REALIZA EL CONTACTO VERBAL, DESDE LA LÍNEA IMAGINARIA QUE DIVIDE EL ÁREA DE SEGURIDAD Y LA DE RIESGO.', 'EFECTUAR UN REGISTRO VISUAL DEL INTERVENIDO.', '2DA PARTE [CAPÍTULO III] - B.2.b', '185998'),
    (2812, 'SUB-2812', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- COMPLETE CORRECTAMENTE RESPECTO A LA INTERVENCIÓN A UN PRESUNTO INFRACTOR: UNA ACCIÓN QUE AYUDARÁ A MINIMIZAR LOS RIESGOS ES EFECTUAR UN REGISTRO VISUAL DEL INTERVENIDO. ELLO NOS PERMITIRÁ UBICAR CUALQUIER TIPO DE AMENAZA (ARMA U OBJETO). ESTA ACCIÓN SE EFECTÚA (. ................... ), DESDE LA LÍNEA IMAGINARIA QUE DIVIDE EL ÁREA DE SEGURIDAD Y LA DE RIESGO.', 'EN EL MOMENTO QUE EL INTERVENIDO SE ENCUENTRA FRENTE AL POLICÍA QUE REALIZA EL CONTACTO VERBAL.', '2DA PARTE [CAPÍTULO III] - B.2.b', '185999'),
    (2813, 'SUB-2813', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- INTERVENCIÓN A UN PRESUNTO INFRACTOR: PARA EFECTUAR EL ARRESTO, EL EFECTIVO POLICIAL PUEDE UTILIZAR BÁSICAMENTE TRES POSICIONES, LAS CUALES SON: DE PIE, DE RODILLAS, Y TENDIDO O ECHADO. ELIJA LA ALTERNATIVA QUE SE RELACIONE CON LA POSICIÓN DE PIE:', 'ESTA POSICIÓN ES RECOMENDABLE CUANDO EN EL LUGAR DE LA INTERVENCIÓN EXISTE UN MURO, PARED, ETC. DONDE EL INFRACTOR SE PUEDA APOYARSE.', '2DA PARTE [CAPÍTULO III] - B.2.b', '186000'),
    (2814, 'SUB-2814', 'SBM5', '¿QUÉ ASPECTOS IMPORTANTES SE TIENEN QUE TENER EN CUENTA EN LAS TÉCNICAS DE INTERVENCIÓN?', 'LA ACTITUD DE LA PERSONA A SER INTERVENIDA.', '2DA PARTE [CAPÍTULO III] - B.1.a', '186001'),
    (2815, 'SUB-2815', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- INTERVENCIÓN A UN PRESUNTO INFRACTOR: PARA EFECTUAR EL ARRESTO, EL EFECTIVO POLICIAL PUEDE UTILIZAR BÁSICAMENTE TRES POSICIONES, LAS CUALES SON: DE PIE, DE RODILLAS, Y TENDIDO O ECHADO. SI DURANTE LA EJECUCIÓN DEL PROCEDIMIENTO DEL ARRESTO EN LA POSICIÓN TENDIDO O ECHADO, EL INTERVENIDO SE TORNA VIOLENTO, EL EFECTIVO POLICIAL DE CONTACTO SE ALEJARA RÁPIDAMENTE DE ÉL, RETORNANDO A SU ÁREA DE SEGURIDAD EMPUÑANDO SU ARMA, Y REINICIANDO LA (. ................ ) PARA RETOMAR EL PROCEDIMIENTO.', 'VERBALIZACIÓN', '2DA PARTE [CAPÍTULO III] - B.2.b', '186002'),
    (2816, 'SUB-2816', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- INTERVENCIÓN A UN PRESUNTO INFRACTOR: PARA EFECTUAR EL ARRESTO, EL EFECTIVO POLICIAL PUEDE UTILIZAR BÁSICAMENTE TRES POSICIONES, LAS CUALES SON: DE PIE, DE RODILLAS, Y TENDIDO O ECHADO. SI DURANTE LA EJECUCIÓN DEL PROCEDIMIENTO DEL ARRESTO EN LA POSICIÓN TENDIDO O ECHADO, EL INTERVENIDO SE TORNA VIOLENTO, EL (. ................... ) SE ALEJARA RÁPIDAMENTE DE ÉL, RETORNANDO A SU ÁREA DE SEGURIDAD EMPUÑANDO SU ARMA, Y REINICIANDO LA VERBALIZACIÓN PARA RETOMAR EL PROCEDIMIENTO.', 'POLICÍA DE CONTACTO.', '2DA PARTE [CAPÍTULO III] - B.2.b', '186003'),
    (2817, 'SUB-2817', 'SBM5', 'LA PERCEPCIÓN DEL RIESGO ES UNO DE LOS ASPECTOS IMPORTANTES QUE SE TIENEN QUE TENER EN CUENTA EN LAS TECNICAS DE INTERVENCION, Y SE REFIERE A: Derechos Humanos aplicados a la Función Policial - 2da parte', 'SE DEBE CONSIDERAR LAS CARACTERÍSTICAS DEL LUGAR DE LA INTERVENCIÓN (UBICACIÓN, ESTRUCTURAS DESCONOCIDAS, CALLEJONES, EDIFICACIONES, ILUMINACIÓN, ENTRE OTROS) QUE PUEDAN REPRESENTAR UN RIESGO PARA LA INTEGRIDAD DEL EFECTIVO POLICIAL O DE TERCEROS, ASÍ COMO EL POSIBLE APOYO DE OTRAS PERSONAS AL INFRACTOR', '2DA PARTE [CAPÍTULO III] - B.1.b', '186004'),
    (2818, 'SUB-2818', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- INTERVENCIÓN A UN PRESUNTO INFRACTOR: PARA EFECTUAR EL ARRESTO, EL EFECTIVO POLICIAL PUEDE UTILIZAR BÁSICAMENTE TRES POSICIONES, LAS CUALES SON: DE PIE, DE RODILLAS, Y TENDIDO O ECHADO. DURANTE LA EJECUCIÓN DEL PROCEDIMIENTO DEL ARRESTO EN LA POSICIÓN DE RODILLAS, EFECTUADO EL CONTACTO VISUAL E INICIADA LA VERBALIZACIÓN, SE ORDENARÁ AL INTERVENIDO COLOCARSE FRENTE A LOS POLICÍAS, A UNA DISTANCIA (. ............. ), FORMANDO EL TRIÁNGULO DE SEGURIDAD; SE LE INDICA QUE LEVANTE LOS BRAZOS, CON LAS MANOS TOTALMENTE ALEJADAS UNA DE OTRA Y LOS DEDOS SEPARADOS.', 'QUE PERMITA DOMINAR LA SITUACIÓN.', '2DA PARTE [CAPÍTULO III] - B.2.b', '186005'),
    (2819, 'SUB-2819', 'SBM5', 'INTERVENCIÓN A PERSONAS EN LA VÍA POR EFECTIVOS POLICIALES A PIE.- INTERVENCIÓN A UN PRESUNTO INFRACTOR: PARA EFECTUAR EL ARRESTO, EL EFECTIVO POLICIAL PUEDE UTILIZAR BÁSICAMENTE TRES POSICIONES, LAS CUALES SON: DE PIE, DE RODILLAS, Y TENDIDO O ECHADO. DURANTE LA EJECUCIÓN DEL PROCEDIMIENTO DEL ARRESTO EN LA POSICIÓN DE RODILLAS, LUEGO DE COLOCARLE LAS GRILLETES SE PROCEDERÁ ....:', 'AL REGISTRO MINUCIOSO DEL INFRACTOR.', '2DA PARTE [CAPÍTULO III] - B.2.b', '186006'),
    (2820, 'SUB-2820', 'SBM5', 'LA POLICÍA DE SEGURIDAD EN LA POSICIÓN DE TENDIDO O ECHADO DEBE VERBALIZAR PARA OBTENER INFORMACIÓN Y NO PERMITIR QUE EL INTERVENIDO SE CONCENTRE EN:', 'PLANIFICAR UNA RESPUESTA VIOLENTA CONTRA LA ACCIÓN DEL POLICÍA DE CONTACTO.', '2DA PARTE [CAPÍTULO III] - B.2.b', '186007'),
    (2821, 'SUB-2821', 'SBM5', 'RESPECTO A LAS TÉCNICAS DE INTERVENCIÓN, EN CASO QUE LA INTERVENCIÓN SEA EJECUTADA POR DOS POLICIAS A PIE, ÉSTOS DEBEN FORMAR EN LO POSIBLE UN (. ....................... ), EN CUYA BASE DEBEN UBICARSE LOS POLICÍAS INTERVENTORES, Y EN EL VÉRTICE O PUNTO MEDIO PROYECTADO DEL TRIÁNGULO.', 'TRIÁNGULO DE SEGURIDAD.', '2DA PARTE [CAPÍTULO III] - B', '186008'),
    (2822, 'SUB-2822', 'SBM5', 'AL SER COMUNICADO DE UNA INTERVENCIÓN EN INMUEBLES O EN OTROS LUGARES QUE AMERITEN DESPLAZARSE POR UNA ZONA NO RECONOCIDA E INSEGURA, SE DEBE UTILIZAR LOS PRINCIPIOS DEL PENSAMIENTO TÁCTICO PARA EVALUAR LAS POSIBLES ÁREAS DE RIESGO. SE DEBEN ANTICIPAR LAS SITUACIONES PELIGROSAS Y MANTENERSE LISTOS PARA DEFENDERSE. EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'INTERVENCIÓN EN INMUEBLES: DESPLAZAMIENTOS.', '2DA PARTE [CAPÍTULO III] - B.4.c', '186009'),
    (2823, 'SUB-2823', 'SBM5', 'SE DEBE TENER SIEMPRE PRESENTE QUE POR MÁS INFORMACIÓN QUE SE OBTENGA DEL INMUEBLE, LOS AMBIENTES INTERIORES CONSTITUYEN ZONAS DE RIESGO PERMANENTE. ESTAS ZONAS SON CONTROLADAS Y CONVERTIDAS EN ÁREAS SEGURAS UNA POR UNA. OTRO ASPECTO A CONSIDERAR ES EL DISEÑO Y MATERIAL EMPLEADOS EN SU CONSTRUCCIÓN, ELLO CONLLEVA UN TRABAJO PROFESIONAL ALTAMENTE COORDINADO, DONDE PRIME LA SEGURIDAD COMO NORMA BÁSICA Y SE LA EJECUTE CON SIGILO, DINAMISMO, DESTREZA Y CONTROL EMOCIONAL. EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'INTERVENCIÓN EN INMUEBLES: RECONOCIMIENTO.', '2DA PARTE [CAPÍTULO III] - B.4.a', '186010'),
    (2824, 'SUB-2824', 'SBM5', 'EN CASO QUE LA INTERVENCIÓN SEA EJECUTADA POR DOS POLICÍAS A PIE, ÉSTOS DEBEN FORMAR EN LO POSIBLE UN TRIÁNGULO DE SEGURIDAD, EN CUYA BASE DEBEN UBICARSE:', 'LOS POLICÍAS INTERVENTORES', '2DA PARTE [CAPÍTULO III] - B', '186011'),
    (2825, 'SUB-2825', 'SBM5', 'DENTRO DE UN INMUEBLE EL CONTROL DE UNA ESCALERA ES UNA ACCIÓN DE GRAN RIESGO Y PELIGRO. LA COORDINACIÓN, COMUNICACIÓN Y COOPERACIÓN SON ABSOLUTAMENTE NECESARIAS. LA TÉCNICA A EMPLEARSE SE DEBERÁ ACONDICIONAR AL TIPO, ESTRUCTURA Y UBICACIÓN ESPECÍFICA DE LA ESCALERA, TENIENDO ESPECIAL CUIDADO EN LOS DESCANSOS. SI SE TIENE HERRAMIENTAS DE OBSERVACIÓN DEBERÁN SER EMPLEADAS. EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'INTERVENCIÓN EN INMUEBLES: ESCALERAS', '2DA PARTE [CAPÍTULO III] - B.4.e', '186012'),
    (2826, 'SUB-2826', 'SBM5', 'INTERVENCIÓN EN INMUEBLES.- RECONOCIMIENTO.- ¿CUÁL ES EL MAYOR PROBLEMA EN LA INTERVENCIÓN EN INMUEBLES?', 'LOS PUNTOS DE ENTRADA O INGRESO.', '2DA PARTE [CAPÍTULO III] - B.4.a', '186013'),
    (2827, 'SUB-2827', 'SBM5', 'INTERVENCIÓN EN INMUEBLES.- INDIQUE LA ALTERNATIVA QUE SE RELACIONE CON LA SIGUIENTE TÉCNICA DE INGRESO A INMUEBLES: EL PERONAL POLICIAL INTERVINIENTES SE DEBEN UBICAR A AMBOS LADOS DE LA PUERTA, ORIENTANDO SUS ARMAS HACIA ÉSTA. EL MÁS CARACTERIZADO SEÑALA CUÁNDO HAY QUE MOVERSE. RECORDAR: EL QUE INGRESE PRIMERO DEBERÁ CUBRIR LA PARTE DE LA HABITACIÓN QUE GENERALMENTE ESTÁ DEL LADO DE LAS BISAGRAS.', 'INGRESO EN X', '2DA PARTE [CAPÍTULO III] - B.4.b.(2)', '186014'),
    (2828, 'SUB-2828', 'SBM5', 'INTERVENCIÓN EN INMUEBLES.- INDIQUE LOS TIPOS DE INGRESO, QUE PUEDE APLICAR UN EFECTIVO PNP AL MOMENTO QUE PARTICIPA EN LA INTERVENCIÓN A UN INMUEBLE:', 'INGRESO DINÁMICO, INGRESO EN X, INGRESO EN J, INGRESO POR EL LADO LARGO, INGRESÓ POR EL LADO CORTO, INGRESO POR BARRIDA O GANADA DE ANGULO(CORTE PASTEL).', '2DA PARTE [CAPÍTULO III] - B.4.b.(1,2,3,4,5,6)', '186015'),
    (2829, 'SUB-2829', 'SBM5', 'INTERVENCIÓN EN INMUEBLES.- INDIQUE LA ALTERNATIVA QUE SE RELACIONE CON LA SIGUIENTE TÉCNICA DE INGRESO A INMUEBLES: SE ENTIENDE POR LADO LARGO, LA MAYOR EXTENSIÓN DE PARED EN LA QUE ESTÁ LA PUERTA; LOS DOS EFECTIVOS POLICIALES ESTÁN EN EL MISMO LADO DE LA PARED; EL PRIMER EFECTIVO POLICIAL DEBE ASEGURARSE QUE LA PUERTA NO ESTÉ CERRADA O TRANCADA.', 'INGRESO POR EL LADO LARGO.', '2DA PARTE [CAPÍTULO III] - B.4.b.(4)', '186016'),
    (2830, 'SUB-2830', 'SBM5', '¿QUÉ ASPECTOS IMPORTANTES SE TIENEN QUE TENER EN CUENTA EN LAS TÉCNICAS DE INTERVENCIÓN?', 'LA PERCEPCIÓN DEL RIESGO.', '2DA PARTE [CAPÍTULO III] - B.1.b', '186017'),
    (2831, 'SUB-2831', 'SBM5', '¿BAJO QUÉ CIRCUNSTANCIAS SE PUEDE QUEBRANTAR LOS PRINCIPIOS DE DERECHO NACIONAL E INTERNACIONAL QUE REGULAN LA RESPUESTA A UNA CRISIS?', 'BAJO NINGUNA CIRCUNSTANCIA.', '2DA PARTE [CAPÍTULO V] - A', '186018'),
    (2832, 'SUB-2832', 'SBM5', 'CON FRECUENCIA LOS EFECTIVOS POLICIALES SON LESIONADOS POR ALGO QUE NO ANTICIPARON, NO RESPONDIERON NI ESTABAN MENTALMENTE PREPARADOS PARA ENFRENTAR;. EL SIGUIENTE ENUNCIADO CORRESPONDE AL:', 'NIVEL DE ATENCIÓN.', '2DA PARTE [CAPÍTULO I] - D.2', '186019'),
    (2833, 'SUB-2833', 'SBM5', 'DEBEN GARANTIZAR UNA ALTA PROFESIONALIZACIÓN, INDIVIDUAL Y COLECTIVA, INCIDIENDO EN ASPECTOS IMPORTANTES PARA EL DESARROLLO DE LA FUNCIÓN POLICIAL COMO SON: USO DE LA FUERZA, ARMAS DE FUEGO, TÉCNICAS DE INTERVENCIÓN POLICIAL, TÁCTICAS DEFENSIVAS NO LETALES, CONTROL FÍSICO DE INTERVENIDOS, ÉTICA EN LA FUNCIÓN POLICIAL. ESTA INSTRUCCIÓN SE DEBE MANTENER EN LOS DIFERENTES NIVELES EDUCATIVOS. TAMBIÉN SE DEBE GARANTIZAR UNA EVALUACIÓN REAL SOSTENIDA QUE PERMITA APRECIAR LA CALIFICACIÓN DE LA APTITUD Y ACTITUD PARA CUMPLIR CON LA FUNCIÓN POLICIAL. EL PÁRRAFO ANTERIOR SE REFIERE A:', 'LOS PLANES Y PROGRAMAS DEL SISTEMA EDUCATIVO POLICIAL.', '2DA PARTE [CAPÍTULO I]', '186020'),
    (2834, 'SUB-2834', 'SBM5', 'VERIFICAR QUE EL PERSONAL ESTÉ ADECUADAMENTE EQUIPADO. EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'ANTES DE LA EJECUCIÓN DE LAS OPERACIONES.', '2DA PARTE [CAPÍTULO IV] - C.1.b', '186021'),
    (2835, 'SUB-2835', 'SBM5', 'A QUE NIVEL DE ALERTA CORRESPONDE EL SIGUIENTE ENUNCIADO: SE DISTRAE CON LO QUE ESTÁ SUCEDIENDO A SU ALREDEDOR, LO QUE PUEDE SER OCASIONADO POR EL CANSANCIO O LA CREENCIA DE QUE NO HAY POSIBILIDAD DE PROBLEMAS.', 'NIVEL DE DISTRACCIÓN.', '2DA PARTE [CAPÍTULO I] - D.1', '186022'),
    (2836, 'SUB-2836', 'SBM5', 'LAS EMOCIONES COMO LA CÓLERA, LA IRA, LA COMPASIÓN, EL MIEDO, ENTRE OTRAS, SON ESTADOS DE ÁNIMO QUE INFLUYEN DIRECTAMENTE EN EL ACCIONAR DEL PERSONAL POLICIAL. ESTE ENUNCIADO ESTÁ RELACIONADO A:', 'CONTROL DE EMOCIONES E INTELIGENCIA EMOCIONAL', '2DA PARTE [CAPÍTULO I] - B.1', '186023'),
    (2837, 'SUB-2837', 'SBM5', 'INTERVENCIÓN EN INMUEBLES.- INDIQUE LA ALTERNATIVA QUE SE RELACIONE CON LA SIGUIENTE TÉCNICA DE INGRESO A INMUEBLES: UBICADOS A UN SOLO LADO DE LA PUERTA O NIVEL DE LA PARED; ES NECESARIO ADOPTAR UNA POSICIÓN CÓMODA Y SEGURA, PUES SE ESTÁ PRESUMIENDO QUE AL DETECTAR UNA AMENAZA SE TENDRÁ QUE EMPLEAR EL ARMA DE FUEGO PARA NEUTRALIZARLE O CONTROLARLA; AMBOS EFECTIVOS POLICIALES DEBERÁN ALEJARSE DE LOS NIVELES DEL MARCO CENTRAL O PARED, PARA EVITAR QUE UNA PERSONA ESCONDIDA DETRÁS DE ELLOS LES PUEDA ARREBATAR EL ARMA.', 'INGRESO POR BARRIDA O GANADA DE ÁNGULO (CORTE PASTEL).', '2DA PARTE [CAPÍTULO III] - B.4.b.(6)', '186024'),
    (2838, 'SUB-2838', 'SBM5', 'RESPECTO A LA DISTRIBUCIÓN TÁCTICA EN EL MANEJO DE CRISIS: ¿POR DÓNDE INGRESAN O SALEN LAS PERSONAS INVOLUCRADAS?', 'POR EL PUNTO DE ENCUENTRO.', '2DA PARTE [CAPÍTULO V] - C.4', '186025'),
    (2839, 'SUB-2839', 'SBM5', 'CRISIS ES ...:', 'ES LA ALTERACIÓN GRAVE DEL ORDEN PÚBLICO', '2DA PARTE [CAPÍTULO V] - A', '186026'),
    (2840, 'SUB-2840', 'SBM5', 'RESPECTO A LA INSTRUCCIÓN BÁSICA: LA PREPARACIÓN DE LOS Y LAS POLICÍAS CONSTITUYA UN PROCESO PERMANENTE DE CAPACITACIÓN Y ENTRENAMIENTO QUE DEBE PERMITIRLES DESEMPEÑARSE ADECUADAMENTE ANTE LOS DIVERSOS REQUERIMIENTOS QUE EL CONTEXTO SOCIAL PRESENTA DURANTE EL CUMPLIMIENTO DE:', 'SU MISIÓN', '2DA PARTE [CAPÍTULO I]', '186027'),
    (2841, 'SUB-2841', 'SBM5', 'RESPECTO A LA INSTRUCCIÓN BÁSICA: ESTA INSTRUCCIÓN SE DEBE MANTENER EN LOS DIFERENTES NIVELES EDUCATIVOS. TAMBIÉN SE DEBE GARANTIZAR UNA EVALUACIÓN REAL SOSTENIDA QUE PERMITA APRECIAR LA CALIFICACIÓN DE LA APTITUD Y ACTITUD PARA CUMPLIR CON:', 'LA FUNCIÓN POLICIAL.', '2DA PARTE [CAPÍTULO I] Derechos Humanos aplicados a la Función Policial - 2da parte', '186028'),
    (2842, 'SUB-2842', 'SBM5', 'RESPECTO A LA PREPARACIÓN PSICOLÓGICA: SI USTED NO SE PREPARA MENTALMENTE PARA LAS SITUACIONES O LO QUE RESULTE DE ELLAS, MUY PROBABLEMENTE TENDRÁ UN DESEMPEÑO NO DESEADO, PUDIENDO INCLUSO QUEDARSE PARALIZADO Y SER VÍCTIMA ....:', 'DE LOS ACONTECIMIENTOS.', '2DA PARTE [CAPÍTULO I] - A', '186029'),
    (2843, 'SUB-2843', 'SBM5', 'INTERVENCIÓN EN INMUEBLES.- DESPLAZAMIENTOS.- INDIQUE LA ALTERNATIVA QUE COMPLETE CORRECTAMENTE EL SIGUIENTE ENUNCIADO: DESPLAZARSE A TRAVÉS DE LA RUTA MÁS SEGURA Y CORTA, BUSCANDO LA PROTECCIÓN DE ABRIGOS (PARAPETOS) SUCESIVOS Y EVITANDO EXPONERSE A RIESGOS INNECESARIOS, ESPECIALMENTE EN ......:', 'ÁREAS LIBRES.', '2DA PARTE [CAPÍTULO III] - B.4.c', '186030'),
    (2844, 'SUB-2844', 'SBM5', 'CONTROL DE EMOCIONES E INTELIGENCIA EMOCIONAL: ¿DE QUÉ DEPENDERÁ SU NIVEL DE ALERTA?', 'DE SU CAPACIDAD DE ANTICIPACIÓN AL PELIGRO.', '2DA PARTE [CAPÍTULO I] - D', '186031'),
    (2845, 'SUB-2845', 'SBM5', '¿CUÁL DE LAS ALTERNATIVAS SE RELACIONA CON UN NIVEL DE SEGURIDAD?', 'HAY CONCIENCIA DE LA EXISTENCIA DE UN PELIGRO. SIN EMBARGO, EL ENTRENAMIENTO, EXPERIENCIA, EDUCACIÓN Y BUEN SENTIDO LE PERMITEN EFECTUAR UN PLANEAMIENTO TÁCTICO A SEGUIR.', '2DA PARTE [CAPÍTULO I] - D.3', '186032'),
    (2846, 'SUB-2846', 'SBM5', '¿CUÁL DE LAS ALTERNATIVAS SE RELACIONA CON EL NIVEL DE ALERTA, NIVEL DE ATENCIÓN?', 'ES EL NIVEL DE ALERTA QUE EL PERSONAL POLICIAL DEBE TENER EN TODO MOMENTO CUANDO ESTÁ PATRULLANDO, DANDO PRIORIDAD A LA BÚSQUEDA DE UNA AMENAZA POTENCIAL.', '2DA PARTE [CAPÍTULO I] - D.2', '186033'),
    (2847, 'SUB-2847', 'SBM5', 'INTERVENCIÓN EN INMUEBLES.- ESCALERAS.- ELIJA LA ALTERNATIVA QUE COMPLETE CORRECTAMENTE EL SIGUIENTE ENUNCIADO: EXISTE MAYOR RIESGO EN CONTROLAR UNA ESCALERA (. ..................... ).', 'HACIA ARRIBA.', '2DA PARTE [CAPÍTULO III] - B.4.e.(1)', '186034'),
    (2848, 'SUB-2848', 'SBM5', '¿CUÁL DE LAS ALTERNATIVAS SE RELACIONA CON EL NIVEL DE ALERTA, NIVEL DE REACCIÓN POSITIVA?', 'EL RIESGO ES REAL Y LA REACCIÓN DEBE SER INSTANTÁNEA.', '2DA PARTE [CAPÍTULO I] - D.4.a', '186035'),
    (2849, 'SUB-2849', 'SBM5', '¿CUÁLES SON LAS DOS ÁREAS QUE SE DEBE DELIMITAR OBJETIVAMENTE PARA UN BUEN PENSAMIENTO TÁCTICO?', 'ÁREA DE SEGURIDAD Y ÁREA DE RIESGO.', '2DA PARTE [CAPÍTULO I] - C.1 y 2', '186036'),
    (2850, 'SUB-2850', 'SBM5', 'EL ÁREA DE RIESGO YA DOMINADA SE CONVIERTE EN:', 'ÁREA DE SEGURIDAD.', '2DA PARTE [CAPÍTULO I] - C.2', '186037'),
    (2851, 'SUB-2851', 'SBM5', 'INDIQUE LA ALTERNATIVA CORRECTA RESPECTO A LA VERBALIZACIÓN:', 'LA POSICIÓN EN LA QUE EL POLICÍA SOSTIENE SU ARMA TAMBIÉN AYUDA EN LA VERBALIZACIÓN.', '2DA PARTE [CAPÍTULO I] - E', '186038'),
    (2852, 'SUB-2852', 'SBM5', 'RESPECTO A LOS NIVELES DE RESPUESTA DEL MANEJO DE UNA CRISIS. INDIQUE, ¿CUÁL DE ÉSTAS REQUIERE LA INTERVENCIÓN DIRECTA DE UNIDADES ESPECIALIZADAS DE LA POLICÍA?', 'ALTÍSIMO RIESGO. Derechos Humanos aplicados a la Función Policial - 2da parte', '2DA PARTE [CAPÍTULO V] - B.2', '186039'),
    (2853, 'SUB-2853', 'SBM5', 'RESPECTO A LOS NIVELES DE RESPUESTA DEL MANEJO DE UNA CRISIS. INDIQUE, ¿CUÁL DE ÉSTAS PUEDE COMPROMETER LA INTERVENCIÓN DE LAS MÁS ALTAS AUTORIDADES DEL SECTOR?', 'ALTÍSIMO RIESGO.', '2DA PARTE [CAPÍTULO V] - B.2', '186040'),
    (2854, 'SUB-2854', 'SBM5', 'RESPECTO A LOS NIVELES DE RESPUESTA DEL MANEJO DE UNA CRISIS. INDIQUE, ¿CUÁL DE ÉSTAS ES NECESARIA LA PARTICIPACIÓN DE OTROS SECTORES Y ORGANISMOS DEL ESTADO, PUDIENDO COMPROMETER LA INTERVENCIÓN DE LAS MÁS ALTAS AUTORIDADES DEL GOBIERNO?', 'RIESGO EXTRAORDINARIO.', '2DA PARTE [CAPÍTULO V] - B.3', '186041'),
    (2855, 'SUB-2855', 'SBM5', 'RESPECTO A LOS NIVELES DE RESPUESTA DEL MANEJO DE UNA CRISIS. INDIQUE, ¿CUÁL DE ÉSTAS SIEMPRE COMPROMETERÁ LA INTERVENCIÓN DE LAS MÁS ALTAS AUTORIDADES DEL GOBIERNO, EN COORDINACIÓN CON ORGANIZACIONES INTERNACIONALES U OTROS ESTADOS?', 'RIESGO EXCEPCIONAL.', '2DA PARTE [CAPÍTULO V] - B.4', '186042'),
    (2856, 'SUB-2856', 'SBM5', 'RESPECTO A LOS NIVELES DE RESPUESTA DEL MANEJO DE UNA CRISIS, INDIQUE DONDE SE ENMARCAN LOS NIVELES DE RESPUESTA DE LA POLICÍA:', 'EN LOS PRINCIPIOS DEL USO DE LA FUERZA.', '2DA PARTE [CAPÍTULO V] - B', '186043'),
    (2857, 'SUB-2857', 'SBM5', 'INDIQUE, ¿CUÁL DE LAS SIGUIENTES ALTERNATIVAS CORRESPONDE PROCEDIMIENTO PARA EL MANEJO DE CRISIS?', 'CONTENER', '2DA PARTE [CAPÍTULO V] - D.1', '186044'),
    (2858, 'SUB-2858', 'SBM5', '¿CUÁL DE LAS SIGUIENTES ALTERNATIVAS CORRESPONDE AL PROCEDIMIENTO PARA EL MANEJO DE CRISIS?', 'NEGOCIAR', '2DA PARTE [CAPÍTULO V] - D.3', '186045'),
    (2859, 'SUB-2859', 'SBM5', '¿EN QUÉ PASO DEL PROCEDIMIENTO PARA EL MANEJO DE CRISIS SE IMPEDIRÁ EL ACCESO DE PERSONAS AJENAS AL EVENTO, FACILITANDO LA SALIDA Y EVACUACIÓN DE LA ZONA DE RIESGO?', 'AISLAR', '2DA PARTE [CAPÍTULO V] - D.2', '186046'),
    (2860, 'SUB-2860', 'SBM5', 'RESPECTO AL MANEJO DE UNA CRISIS INDIQUE: A FALTA DE UN NEGOCIADOR PROFESIONAL DE LA POLICÍA ¿QUIÉN DEBE ESTAR A CARGO DE LAS NEGOCIACIONES?', 'EL EFECTIVO POLICIAL QUE REÚNA LAS CONDICIONES PARA DESEMPEÑARSE COMO TAL.', '2DA PARTE [CAPÍTULO V] - D', '186047'),
    (2861, 'SUB-2861', 'SBM5', 'RESPECTO A LA GUÍA PARA NEGOCIADORES NO ENTRENADOS INDIQUE QUE ES LO QUE NO SE DEBE HACER CON EL CAUSANTE:', 'PREGUNTAR POR SUS EXIGENCIAS.', '2DA PARTE [CAPÍTULO V] - E.6.d', '186048'),
    (2862, 'SUB-2862', 'SBM5', 'RESPECTO A LA GUÍA PARA NEGOCIADORES NO ENTRENADOS INDIQUE: ¿QUÉ ES LO QUE NO SE DEBE HACER CON EL CAUSANTE?', 'PRESENTARSE COMO EL QUE VA A TOMAR LAS DECISIONES.', '2DA PARTE [CAPÍTULO V] - E.6.h', '186049'),
    (2863, 'SUB-2863', 'SBM5', 'DE EXISTIR DETENIDOS, LESIONADOS O MUERTOS, COMUNICAR DE INMEDIATO A SUS FAMILIARES. EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'DESPUÉS DE LA EJECUCIÓN DE LAS OPERACIONES.', '2DA PARTE [CAPÍTULO IV] - C.3.b', '186050'),
    (2864, 'SUB-2864', 'SBM5', 'DEJAR DE UTILIZAR LA FUERZA INMEDIATAMENTE AL CESE DE LA RESISTENCIA O VIOLENCIA, ADOPTANDO LAS CORRESPONDIENTES MEDIDAS DE SEGURIDAD. EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'DURANTE LA EJECUCIÓN DE LAS OPERACIONES', '2DA PARTE [CAPÍTULO IV] - C.2.q', '186051'),
    (2865, 'SUB-2865', 'SBM5', 'QUE NIVEL DE ALERTA CORRESPONDE EL SIGUIENTE ENUNCIADO: NO ES UNA GARANTÍA DE PROTECCIÓN, PERO NOS DARÁ MEJORES CONDICIONES PARA DETECTAR UN PELIGRO Y, DE SER EL CASO, PASAR A UN ESTADO O NIVEL DE REACCIÓN.', 'NIVEL DE ATENCIÓN.', '2DA PARTE [CAPÍTULO I] - D.2', '186052'),
    (2866, 'SUB-2866', 'SBM5', 'EN ESTAS SITUACIONES SE REQUIERE LA INTERVENCIÓN DIRECTA DE UNIDADES ESPECIALIZADAS DE LA POLICÍA. PUEDE COMPROMETER LA INTERVENCIÓN DE LAS MÁS ALTAS AUTORIDADES DEL SECTOR.¿A QUÉ NIVEL DE RESPUESTA A LA CRISIS CORRESPONDE?:', 'ALTÍSIMO RIESGO.', '2DA PARTE [CAPÍTULO V] - B.2', '186053'),
    (2867, 'SUB-2867', 'SBM5', 'EN LA INSTRUCCIÓN BÁSICA.- PREPARACIÓN PSICOLÓGICA.- LOS NIVELES DE ALERTA SON:', 'NIVEL DE DISTRACCIÓN, NIVEL DE ATENCIÓN, NIVEL DE SEGURIDAD Y NIVEL DE REACCIÓN.', '2DA PARTE [CAPÍTULO I] - D', '186054'),
    (2868, 'SUB-2868', 'SBM5', 'PRIORIZAR EL NIVEL PREVENTIVO DEL EMPLEO DE LA FUERZA CUANDO SE DISPERSEN REUNIONES NO VIOLENTAS. EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'DURANTE LA EJECUCIÓN DE LAS OPERACIONES.', '2DA PARTE [CAPÍTULO IV] - C.2.c', '186055'),
    (2869, 'SUB-2869', 'SBM5', 'NO ARREBATAR BANDEROLAS O PANCARTAS UTILIZADAS POR LOS MANIFESTANTES PARA NO EXACERBAR LOS ÁNIMOS, LIMITÁNDOSE AL DECOMISO DE OBJETOS CONTUNDENTES O PUNZO CORTANTES QUE PUEDAN SER UTILIZADOS CONTRA LAS PERSONAS (CIVILES O POLICÍAS). EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'DURANTE LA EJECUCIÓN DE LAS OPERACIONES.', '2DA PARTE [CAPÍTULO IV] - C.2.l', '186056'),
    (2870, 'SUB-2870', 'SBM5', 'ES EL ÁREA DONDE EL POLICÍA TIENE EL DOMINIO DE LA SITUACIÓN DESPUÉS DE UNA ACCIÓN DE CONTROL QUE LE PERMITE MINIMIZAR CUALQUIER RIESGO PARA SU INTEGRIDAD FÍSICA Y LA DE SUS COMPAÑEROS:', 'ÁREA DE SEGURIDAD', '2DA PARTE [CAPÍTULO I] - C.1', '186057'),
    (2871, 'SUB-2871', 'SBM5', 'ES LA HERRAMIENTA O RECURSO MÁS UTILIZADO EN UNA INTERVENCIÓN POLICIAL, MEDIANTE EL QUE SE TRATA DE MANTENER O RESTABLECER EL PRINCIPIO DE AUTORIDAD A TRAVÉS DEL EMPLEO DE LA EXPRESIÓN ORAL, CON LA FIRMEZA Y ENERGÍA ADECUADA A CADA SITUACIÓN PARTICULAR:', 'VERBALIZACIÓN.', '2DA PARTE [CAPÍTULO I] - E', '186058'),
    (2872, 'SUB-2872', 'SBM5', 'MEDIOS DE POLICÍA.- PARA EL CUMPLIMIENTO DE SU SERVICIO, EL PERSONAL POLICIAL DEBE CONTAR CON UN EQUIPAMIENTO BÁSICO, CONFORMADO PRINCIPALMENTE POR:', 'BASTONES POLICIALES, GRILLETES POLICIALES, CHALECO BALÍSTICO, ARMA DE FUEGO Y MUNICIÓN REGLAMENTARIA Y CINTO POLICIAL.', '2DA PARTE [CAPÍTULO I] - F', '186059'),
    (2873, 'SUB-2873', 'SBM5', 'NO PODEMOS DEJAR DE MENCIONAR QUE SEGÚN LA ESPECIALIDAD FUNCIONAL HAY UNIDADES POLICIALES QUE DEBEN CONTAR CON OTROS MEDIOS DISPONIBLES MENOS LESIVOS PARA TUTELAR LA VIDA E INTEGRIDAD DE LA PERSONA O SITUACIÓN QUE SE PRETENDE PROTEGER; TALES COMO:', 'CASCO PROTECTOR, MÁSCARA ANTIGÁS, PROTECTORES CORPORALES, ESCUDOS, ESCOPETAS LANZA GAS Y ESCOPETAS DE CAZA.', '2DA PARTE [CAPÍTULO I] - F.6.b', '186060'),
    (2874, 'SUB-2874', 'SBM5', 'DEFENSA DE GOMA.- EL EMPUÑAMIENTO DE LA DEFENSA DE GOMA PUEDE SER DE DOS FORMAS:', 'TOMA CORTA Y TOMA LARGA', '2DA PARTE [CAPÍTULO I] - F.1.a).(2)', '186061'),
    (2875, 'SUB-2875', 'SBM5', 'INDIQUE LA FORMA DE EMPUÑAMIENTO DE LA DEFENSA DE GOMA CORRESPONDE AL SIGUIENTE CONCEPTO: SE SUJETA LA DEFENSA DE GOMA LO MÁS CERCA DEL EXTREMO SUPERIOR DONDE ESTÁ EL REVESTIMIENTO FINAL DEL CUERO EN MAYOR DIÁMETRO.', 'TOMA LARGA', '2DA PARTE [CAPÍTULO I] - F.1.a).(2).(b)', '186062'),
    (2876, 'SUB-2876', 'SBM5', 'REDUCEN LAS POSIBILIDADES DE LA PERSONA INTERVENIDA DE AGREDIR AL PERSONAL POLICIAL, GARANTIZANDO SU INTEGRIDAD FÍSICA Y LA DE SUS COMPAÑEROS. ESTE ENUNCIADO CORRESPONDE A:', 'GRILLETES POLICIALES', '2DA PARTE [CAPÍTULO I] - F.5', '186063'),
    (2877, 'SUB-2877', 'SBM5', 'EL USO DEL ARMA ES:', 'EXCEPCIONAL', '2DA PARTE [CAPÍTULO I] - F.6.b', '186064'),
    (2878, 'SUB-2878', 'SBM5', 'SE DESENFUNDA EL ARMA EXTENDIENDO LOS BRAZOS HACIA EL OBJETIVO, APUNTANDO DIRECTAMENTE AL CENTRO DE LA MASA CORPORAL. LA EVALUACIÓN DE LA AMENAZA A LA VIDA O A LA INTEGRIDAD DETERMINARÁ SI EXISTE LA NECESIDAD DE DISPARAR. EL ENUNCIADO ANTERIOR CORRESPONDE A UNA POSICIÓN BÁSICA DE TIRO DENOMINADA:', 'POSICIÓN DE POTENCIAL DISPARO (POSICIÓN 4).', '2DA PARTE [CAPÍTULO I] - F.6.a.(5)', '186065'),
    (2879, 'SUB-2879', 'SBM5', 'EN DEFENSA PROPIA O DE OTRAS PERSONAS EN CASO DE PELIGRO INMINENTE DE MUERTE O LESIONES GRAVES. EN ESTE CASO EL POLICÍA PODRÁ UTILIZAR EN FORMA EXCEPCIONAL ...:', 'SU ARMA DE FUEGO.', '2DA PARTE [CAPÍTULO I] - F.6.b', '186066'),
    (2880, 'SUB-2880', 'SBM5', 'PROCEDIMIENTOS PARA EL EMPLEO DE ARMAS DE FUEGO.- CUANDO SE HAYAN PRODUCIDO HERIDOS COMO CONSECUENCIA DEL DISPARO DE ARMAS DE FUEGO, SE PROCEDERÁ:', 'AL AUXILIO INMEDIATO.', '2DA PARTE [CAPÍTULO I] - F.6.b', '186067'),
    (2881, 'SUB-2881', 'SBM5', 'ES EL MEDIO QUE EN SUS DIFERENTES NIVELES USA EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, DENTRO DEL MARCO DE LA LEY, PARA LOGRAR EL CONTROL DE UNA SITUACIÓN QUE CONSTITUYE UNA AMENAZA O ATENTA CONTRA LA SEGURIDAD, EL ORDEN PÚBLICO, LA INTEGRIDAD O LA VIDA DE LAS PERSONAS. EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'DEFINICIÓN DE FUERZA EN EL ACCIONAR POLICIAL.', '2DA PARTE [CAPÍTULO II]', '186068'),
    (2882, 'SUB-2882', 'SBM5', 'EL USO DE LA FUERZA EN EL CUMPLIMIENTO DEL DEBER ES NECESARIO CUANDO OTROS MEDIOS RESULTEN INEFICACES O NO GARANTICEN DE NINGUNA MANERA EL LOGRO DEL OBJETIVO LEGAL BUSCADO. EL ENUNCIADO ANTERIOR, CONSTITUYE LA DEFINICIÓN DE UNO DE LOS PRINCIPIOS DEL USO DE LA FUERZA, DENOMINADO:', 'NECESIDAD', '2DA PARTE [CAPÍTULO II] - A.2', '186069'),
    (2883, 'SUB-2883', 'SBM5', 'AL INTERVENIR A PERSONAS EN EL CUMPLIMIENTO DE SU FUNCIÓN, EL PERSONAL POLICIAL ENCONTRARÁ COMO RESPUESTA UNA SERIE DE CONDUCTAS CLASIFICADAS EN NIVELES DE RESISTENCIA, ANTE LO CUAL EL POLICÍA DEBERÁ HACER:', 'UN USO DIFERENCIADO Y PROGRESIVO DE LA FUERZA', '2DA PARTE [CAPÍTULO II] - B', '186070'),
    (2884, 'SUB-2884', 'SBM5', 'ES LA AMENAZA PERMANENTE NO VISIBLE PRESENTE EN TODA INTERVENCIÓN POLICIAL. EL ENUNCIADO ANTERIOR CORRESPONDE A LOS NIVELES DE RESISTENCIA EN EL USO DIFERENCIADO Y PROGRESIVO DE LA FUERZA, DENOMINADO:', 'NIVEL DE RESISTENCIA PASIVA: RIESGO LATENTE', '2DA PARTE [CAPÍTULO II] - B.1.a.(1)', '186071'),
    (2885, 'SUB-2885', 'SBM5', 'TÉCNICAS DE INTERVENCIÓN.- TODA INTERVENCIÓN POLICIAL, POR LO GENERAL, DEBE SER EFECTUADA COMO MÍNIMO POR:', 'DOS POLICIAS', '2DA PARTE [CAPÍTULO III] - B', '186072'),
    (2886, 'SUB-2886', 'SBM5', '¿A QUÉ ASPECTO MUY IMPORTANTE DEL MANTENIMIENTO DEL ORDEN PÚBLICO, CORRESPONDE EL SIGUIENTE ENUNCIADO?: NO ARROJAR CONTRA LOS MANIFESTANTES OBJETOS CONTUNDENTES (PIEDRAS, PALOS, FIERROS, ETC.) QUE ESTÉN AL ALCANCE O QUE SEAN LANZADOS AL PERSONAL POLICIAL, MANTENIENDO LAS FORMACIONES TÁCTICAS Y EMPLEANDO ADECUADAMENTE LOS EQUIPOS DE PROTECCIÓN: (SEÑALE LA RESPUESTA CORRECTA)', 'DURANTE LA EJECUCIÓN DE LAS OPERACIONES', '2DA PARTE [CAPÍTULO IV] - C.2.o', '186073'),
    (2887, 'SUB-2887', 'SBM5', 'EL ESTADO DE ALERTA PUEDE SER IDENTIFICADO A TRAVÉS DE LOS SIGUIENTES NIVELES: (SEÑALE LA RESPUESTA CORRECTA)', 'NIVEL DE DISTRACCIÓN', '2DA PARTE [CAPÍTULO I] - D', '186074'),
    (2888, 'SUB-2888', 'SBM5', 'ESTÁ A CARGO DE LOS DIFERENTES NIVELES DE COMANDO (ALTA DIRECCIÓN, DIRECCIÓN EJECUTIVA DE OPERACIONES, DIRECCIONES ESPECIALIZADAS, DIRECCIONES TERRITORIALES Y JEFATURAS DE REGIÓN) QUE ASUMEN LA RESPONSABILIDAD INSTITUCIONAL DE SUPERVISIÓN Y CONTROL DE ACUERDO A LOS OBJETIVOS, ESTRATEGIAS Y POLÍTICAS DEL SECTOR. EL ENUNCIADO ANTERIOR CORRESPONDE A:', 'DIRECCIÓN DE LAS OPERACIONES.', '2DA PARTE [CAPÍTULO IV] - A.1', '186075'),
    (2889, 'SUB-2889', 'SBM5', 'LA POLICÍA NACIONAL DEL PERÚ TIENE COMO FUNCIÓN MANTENER Y RESTABLECER EL ORDEN PÚBLICO, SIENDO NECESARIA UNA ACTUACIÓN PROFESIONAL Y SUSTENTADA EN LOS DERECHOS HUMANOS APLICADOS A LA FUNCIÓN POLICIAL, GARANTIZANDO LA DEFENSA DE LA PERSONA, LA SOCIEDAD Y EL ESTADO:', 'OPERACIONES DE ORDEN PÚBLICO.', '2DA PARTE [CAPÍTULO IV]', '186076'),
    (2890, 'SUB-2890', 'SBM5', 'RESPECTO A LAS TÉCNICAS DE INTERVENCIÓN, LOS EFECTIVOS POLICIALES DEBEN TRAZAR SIEMPRE UNA (. .......................... ) QUE DIVIDA EL ÁREA DE LA INTERVENCIÓN, ESTABLECIENDO EL ÁREA DE SEGURIDAD (DOMINADA POR ELLOS) Y EL ÁREA DE RIESGO (NO CONTROLADA POR ELLOS), EN DONDE SE PRESUMA O SE TENGA LA CERTEZA DE LA PRESENCIA DEL INTERVENIDO O PRESUNTO INFRACTOR.', 'LÍNEA IMAGINARIA.', '2DA PARTE [CAPÍTULO III] - A', '186077'),
    (2891, 'SUB-2891', 'SBM5', 'EN LA INTERVENCIÓN POLICIAL A UN VEHÍCULO CON PRESUNTOS INFRACTORES. INDIQUE, ¿CUÁL DEBE SER LA POSICIÓN DEL VEHÍCULO POLICIAL (PATRULLERO)?', 'EN DIAGONAL (45º APROX.), VÉRTICE ANTERIOR DERECHO EN PROYECCIÓN AL VÉRTICE POSTERIOR IZQUIERDO DEL VEHÍCULO INTERVENIDO.', '2DA PARTE [CAPÍTULO III] - B.3.b', '186078'),
    (2892, 'SUB-2892', 'SBM5', 'ES UN EXCELENTE MEDIO DEFENSIVO QUE PERMITE ESTABLECER UN ÁREA DE SEGURIDAD MAYOR AL DE LA PROTECCIÓN ALCANZADA CON BRAZOS Y PIES. NOS REFERIMOS:', 'A LA DEFENSA DE GOMA', '2DA PARTE [CAPÍTULO I] - F.1.a)', '186079'),
    (2893, 'SUB-2893', 'SBM5', 'ES NECESARIO QUE (........) ESTÉ PREPARADO PROFESIONALMENTE Y MOTIVADO PARA EL DESARROLLO ADECUADO DE ACTITUDES, HABILIDADES, CONFIANZA, ESPÍRITU DE EQUIPO POSITIVO, LIDERAZGO EFICAZ Y LA EJECUCIÓN DE TÁCTICAS OPERACIONALES; ASPECTOS QUE DEBEN FORMAR PARTE DE SU INSTRUCCIÓN Y ENTRENAMIENTO:', 'EL POLICÍA.', '2DA PARTE [CAPÍTULO III] - A', '186080'),
    (2894, 'SUB-2894', 'SBM5', '¿CUÁL DE LAS ALTERNATIVAS SIGUIENTES ES PARTE DE LA DISTRIBUCIÓN TÁCTICA DEL MANEJO DE CRISIS?', 'EQUIPO DE FRANCOTIRADORES', '2DA PARTE [CAPÍTULO V] - C.10', '186081'),
    (2895, 'SUB-2895', 'SBM5', 'POR EL MATERIAL EMPLEADO EN SU FABRICACIÓN, EL USO DE LOS GRILLETES DE SEGURIDAD PUEDE ORIGINAR LESIONES SI SON MAL EMPLEADOS. POR ELLO, EL PERSONAL POLICIAL DEBERÁ POSIBILITAR LA ATENCIÓN MÉDICA NECESARIA EN CASO DE QUE ESTAS LESIONES SE HAYAN PRODUCIDO. EL PÁRRAFO ANTERIOR SE REFIERE A:', 'LOS GRILLETES DE SEGURIDAD', '2DA PARTE [CAPÍTULO I] - F.5.a)', '186082'),
    (2896, 'SUB-2896', 'SBM5', 'LOS NIVELES DE RESPUESTA DE LA POLICÍA, SE ENMARCAN EN LOS PRINCIPIOS DEL USO DE LA FUERZA DESARROLLADOS EN EL MANUAL, Y ESTÁN EN RELACIÓN DIRECTA AL:', 'GRADO DE AMENAZA', '2DA PARTE [CAPÍTULO V] - B', '186083'),
    (2897, 'SUB-2897', 'SBM5', 'DEBEMOS TOMAR CONCIENCIA QUE TODO EMPLEO EXCESIVO DE LA FUERZA SE CONVIERTE EN VIOLENCIA Y ES VISTO COMO UN ACTO ARBITRARIO, ILEGAL, ILEGÍTIMO Y NO PROFESIONAL. POR ELLO, LOS Y LAS POLICÍAS DEBEN TENER PRESENTE SIEMPRE QUE:', 'FUERZA NO ES VIOLENCIA.', '2DA PARTE [CAPÍTULO II]', '186084'),
    (2898, 'SUB-2898', 'SBM5', 'LA SEGURIDAD DEL PERSONAL POLICIAL ESTÁ DIRECTAMENTE RELACIONADA CON SU PREPARACIÓN O ESTADO MENTAL. ESTO LE PERMITIRÁ VISUALIZAR Y ENSAYAR SUS ACCIONES, DE MODO QUE SE TENGA UNA RESPUESTA EN RAZÓN A LA FORMA DE ACTUAR DE LOS PRESUNTOS INFRACTORES DE LA LEY. POR ESTAS MISMAS RAZONES, EL PERSONAL POLICIAL DEBE RECIBIR ORIENTACIÓN PSICOLÓGICA POR CUENTA DEL ESTADO PARA SOBRELLEVAR LAS TENSIONES GENERADAS POR EL USO DE LA FUERZA QUE AFECTEN LA VIDA O INTEGRIDAD FÍSICA DE OTRAS PERSONAS. EL PÁRRAFO ANTERIOR SE REFIERE A:', 'PREPARACIÓN PSICOLÓGICA.', '2DA PARTE [CAPÍTULO I] - A', '186085'),
    (2899, 'SUB-2899', 'SBM5', 'LA INTERVENCIÓN A VEHÍCULOS SE REALIZA PRINCIPALMENTE EN DOS SITUACIONES, LAS CUALES SON:', 'POR INFRACCIÓN AL REGLAMENTO NACIONAL DE TRÁNSITO; Y POR PREVENCIÓN DE DELITOS Y FALTAS.', '2DA PARTE [CAPÍTULO III] - B.3', '186086'),
    (2900, 'SUB-2900', 'SBM5', 'EN LA INTERVENCIÓN POLICIAL DIURNA A UN VEHÍCULO CON PRESUNTOS INFRACTORES DESDE UN VEHÍCULO POLICIAL, ANTE LA PRESENCIA DE UN TERCERO O MÁS OCUPANTES, INDIQUE EL PROCEDIMIENTO CORRECTO:', 'ES RECOMENDABLE HACER DESCENDER, LUEGO DE HABER INTERVENIDO AL CONDUCTOR, A LOS OCUPANTES DEL ASIENTO TRASERO POR LA PUERTA POSTERIOR IZQUIERDA (DETRÁS DE LA DEL CONDUCTOR), PARA MINIMIZAR LA POSIBILIDAD DE UNA TOMA DE REHÉN POR LOS OTROS INFRACTORES', '2DA PARTE [CAPÍTULO III] - B.3.b', '186087')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

WITH data(codigo_pregunta, letra, texto, es_correcta, orden) AS (
  VALUES
    ('SUB-2801', 'A', 'SE DEBE CONSIDERAR LAS CARACTERÍSTICAS DEL LUGAR DE LA INTERVENCIÓN (UBICACIÓN, ESTRUCTURAS DESCONOCIDAS, CALLEJONES, EDIFICACIONES, ILUMINACIÓN, ENTRE OTROS) QUE PUEDAN REPRESENTAR UN RIESGO PARA LA INTEGRIDAD DEL EFECTIVO POLICIAL O DE TERCEROS, ASÍ COMO EL POSIBLE APOYO DE OTRAS PERSONAS AL INFRACTOR.', FALSE, 1),
    ('SUB-2801', 'B', 'EL EFECTIVO POLICIAL DEBE TENER EN CUENTA EL COMPORTAMIENTO DE LA PERSONA A INTERVENIR, QUE PUEDE SER DE COLABORACIÓN, RESISTENCIA PASIVA O ACTIVA, LLEGANDO INCLUSIVE A LA AGRESIÓN LETAL.', FALSE, 2),
    ('SUB-2801', 'C', 'ESTA INTERVENCIÓN SE DEBE INICIAR CON LA VERBALIZACIÓN.', FALSE, 3),
    ('SUB-2801', 'D', 'LUEGO DE UNA APRECIACIÓN DE LA SITUACIÓN Y LAS CIRCUNSTANCIAS QUE SE PRESENTAN EN LA INTERVENCIÓN, EL EFECTIVO POLICIAL EMPLEARÁ LA FUERZA, DE ACUERDO AL NIVEL DE RESISTENCIA DE LA PERSONA A INTERVENIR.', TRUE, 4),
    ('SUB-2801', 'E', 'FORMAR EL CONO DE SEGURIDAD, TOMANDO UNA DISTANCIA APROXIMADA DE DOS BRAZOS EXTENDIDOS, QUE IMPIDA AL INTERVENIDO ATENTAR CONTRA LA INTEGRIDAD FÍSICA DEL O LOS EFECTIVOS POLICIALES; DE EXISTIR UNA PARED (INMUEBLE), EL EFECTIVO QUE DA LA SEGURIDAD DEBE UBICARSE DE ESPALDAS A ÉSTA.', FALSE, 5),
    ('SUB-2802', 'A', 'UNA NO ES EXCLUYENTE DE LA OTRA', TRUE, 1),
