    ('SUB-2802', 'C', 'UNA NO ES INCLUYENTE DE LA OTRA.', FALSE, 3),
    ('SUB-2802', 'D', 'UNA ES INCLUYENTE DE LA OTRA.', FALSE, 4),
    ('SUB-2802', 'E', 'EN OCASIONES AMBAS SITUACIONES NO SE CUMPLEN.', FALSE, 5),
    ('SUB-2803', 'A', 'APOYO POLICIAL.', FALSE, 1),
    ('SUB-2803', 'B', 'INCREMENTO DE LAS FUERZAS AMIGAS.', FALSE, 2),
