    ('SUB-2803', 'D', 'APOYO DE OTRAS PERSONAS AL INFRACTOR', TRUE, 4),
    ('SUB-2803', 'E', 'ATAQUE TERRORISTA.', FALSE, 5),
    ('SUB-2804', 'A', 'A LA FUERZA QUE SE PUEDA EJERCER SOBRE LA PERSONA A INTERVENIR', FALSE, 1),
    ('SUB-2804', 'B', 'A LA EDAD DEL EFECTIVO POLICIAL.', FALSE, 2),
    ('SUB-2804', 'C', 'A LA CONDICIÓN FISICA DEL EFECTIVO POLICIAL.', FALSE, 3),
    ('SUB-2804', 'D', 'A LA EDAD DE LA PERSONA A INTERVENIR', FALSE, 4),
    ('SUB-2804', 'E', 'AL NIVEL DE RESISTENCIA DE LA PERSONA A INTERVENIR.', TRUE, 5),
    ('SUB-2805', 'A', 'IDENTIFICARSE (SALUDO, GRADO, APELLIDOS, UNIDAD EN LA QUE PRESTA SERVICIO), HACIÉNDOLE CONOCER EL MOTIVO DE LA INTERVENCIÓN. Derechos Humanos aplicados a la Función Policial - 2da parte', TRUE, 1),
    ('SUB-2805', 'B', 'PUEDEN PRESENTARSE DURANTE EL PATRULLAJE O A MÉRITO DE UNA COMUNICACIÓN RADIAL O TELEFÓNICA DE LA UNIDAD POLICIAL.', FALSE, 2),
    ('SUB-2805', 'C', 'ESTAS INTERVENCIONES SON LAS QUE REPRESENTAN UN MAYOR NIVEL DE RIESGO PARA LOS EFECTIVOS POLICIALES', FALSE, 3),
    ('SUB-2805', 'D', 'ES DE SUMA IMPORTANCIA QUE LA INFORMACIÓN QUE RECABEN LOS EFECTIVOS QUE VAN A INTERVENIR SEA DETALLADA CON LA FINALIDAD DE TOMAR CONOCIMIENTO DE LA SITUACIÓN.', FALSE, 4),
    ('SUB-2805', 'E', 'EL POLICÍA DEBE IDENTIFICARSE COMO TAL EXPRESANDO EN VOZ ALTA: ¡ALTO POLICÍA!', FALSE, 5),
    ('SUB-2806', 'A', 'EL NÚMERO DE EFECTIVOS.', FALSE, 1),
    ('SUB-2806', 'B', 'EL CONO DE SEGURIDAD.', FALSE, 2),
    ('SUB-2806', 'C', 'LA ZONA DE RIESGO Y LA ZONA DE SEGURIDAD.', FALSE, 3),
    ('SUB-2806', 'D', 'EL NIVEL DE FUERZA A EMPLEAR', TRUE, 4),
    ('SUB-2806', 'E', 'LA LÍNEA IMAGINARIA QUE DIVIDE LA ZONA DE RIESGO Y LA ZONA DE SEGURIDAD', FALSE, 5),
    ('SUB-2807', 'A', 'CULMINADA LA INTERVENCIÓN SIN NOVEDAD, EL POLICÍA DE CONTACTO (P1) AGRADECERÁ SU COLABORACIÓN, DESPLAZÁNDOSE LUEGO HACIA LA UBICACIÓN DEL POLICÍA DE SEGURIDAD (P2), PARA QUE EL CIUDADANO REINICIE SU CAMINO ACOMPAÑÁNDOLO CON LA MIRADA HASTA CIERTA DISTANCIA.', FALSE, 1),
    ('SUB-2807', 'B', 'EFECTUAR PREGUNTAS RELACIONADAS A LOS DATOS CONSIGNADOS EN EL DOCUMENTO DE IDENTIDAD CON LA FINALIDAD DE CONTRASTARLOS, O FORMULAR PREGUNTAS MODIFICANDO ALGUNOS DATOS QUE PERMITAN ESTABLECER LA TITULARIDAD DE LOS MISMOS; POR EJEMPLO, MENCIONARLE COMO SU SEGUNDO NOMBRE UNO QUE NO LE CORRESPONDE.', FALSE, 2),
    ('SUB-2807', 'C', 'SOLICITARLE SUS DOCUMENTOS DE IDENTIFICACIÓN PERSONAL, PERMANECIENDO SIEMPRE EN UNA ACTITUD VIGILANTE, SIN DESCUIDAR EL CONTACTO VISUAL.', FALSE, 3),
    ('SUB-2807', 'D', 'AL VERIFICAR LOS DOCUMENTOS, HACERLO EN UNA POSICIÓN TAL QUE NO OBSTACULICE EL DOMINIO VISUAL, PRINCIPALMENTE DE LAS MANOS DEL INTERVENIDO.', FALSE, 4),
    ('SUB-2807', 'E', 'HACERLE SABER EL MOTIVO DE LA INTERVENCIÓN, POR EJEMPLO: ES USTED SOSPECHOSO DE ........ ; O HA COMETIDO EL DELITO DE ..........;', TRUE, 5),
    ('SUB-2808', 'A', 'ESTAS INTERVENCIONES SON LAS QUE REPRESENTAN UN MAYOR NIVEL DE RIESGO PARA EL PERSONAL POLICIAL. PUEDEN PRESENTARSE DURANTE EL PATRULLAJE O A MÉRITO DE UNA COMUNICACIÓN RADIAL O TELEFÓNICA DE LA UNIDAD POLICIAL. EN ESE SENTIDO, ES DE SUMA IMPORTANCIA QUE LA INFORMACIÓN QUE RECABE EL PERSONAL POLICIAL QUE VA A INTERVENIR SEA DETALLADA CON LA FINALIDAD DE TOMAR CONOCIMIENTO DE LA SITUACIÓN.', TRUE, 1),
    ('SUB-2808', 'B', 'SE INDIVIDUALIZA CLARAMENTE A LA PERSONA A INTERVENIR (VESTIMENTA, CARACTERÍSTICAS FÍSICAS, SEXO, ETC.)', FALSE, 2),
    ('SUB-2808', 'C', 'SE RECIBE LOS DOCUMENTOS CON LA MANO QUE NO PORTE EL ARMA DE FUEGO; ESTO PARA PERMITIR QUE ANTE UNA EVENTUAL REACCIÓN PUEDA USARLA CON LIBERTAD DE ACCIÓN.', FALSE, 3),
    ('SUB-2808', 'D', 'IDENTIFICARSE (GRADO, APELLIDOS Y UNIDAD EN LA QUE PRESTA SERVICIO), HACIÉNDOLE CONOCER EL MOTIVO DE LA INTERVENCIÓN.', FALSE, 4),
    ('SUB-2808', 'E', 'SE SOLICITA SUS DOCUMENTOS DE IDENTIFICACIÓN PERSONAL, PERMANECIENDO SIEMPRE EN UNA ACTITUD VIGILANTE, SIN DESCUIDAR EL CONTACTO VISUAL.', FALSE, 5),
    ('SUB-2809', 'A', 'SE FORMAR EL CONO DE SEGURIDAD, TOMANDO UNA DISTANCIA APROXIMADA DE DOS BRAZOS EXTENDIDOS, QUE IMPIDA AL INTERVENIDO ATENTAR CONTRA LA INTEGRIDAD FÍSICA DEL O LOS EFECTIVOS POLICIALES; DE EXISTIR UNA PARED (INMUEBLE), EL EFECTIVO QUE DA LA SEGURIDAD DEBE UBICARSE DE ESPALDAS A ÉSTA.', FALSE, 1),
    ('SUB-2809', 'B', 'SE INDIVIDUALIZA CLARAMENTE A LA PERSONA A INTERVENIR (VESTIMENTA, CARACTERÍSTICAS FÍSICAS, SEXO, ETC.)', FALSE, 2),
    ('SUB-2809', 'C', 'ESTA INTERVENCION SON LA QUE REPRESENTA UN MAYOR NIVEL DE RIESGO PARA EL PERSONAL POLICIAL.', TRUE, 3),
    ('SUB-2809', 'D', 'IDENTIFICARSE (GRADO, APELLIDOS Y UNIDAD EN LA QUE PRESTA SERVICIO), HACIÉNDOLE CONOCER EL MOTIVO DE LA INTERVENCIÓN.', FALSE, 4),
    ('SUB-2809', 'E', 'SE SOLICITA SUS DOCUMENTOS DE IDENTIFICACIÓN PERSONAL, PERMANECIENDO SIEMPRE EN UNA ACTITUD VIGILANTE, SIN DESCUIDAR EL CONTACTO VISUAL.', FALSE, 5),
    ('SUB-2810', 'A', 'EL POLICÍA DEBE IDENTIFICARSE COMO TAL EXPRESANDO EN VOZ ALTA: ¡ALTO POLICÍA!', FALSE, 1),
    ('SUB-2810', 'B', '¡LEVANTE LAS MANOS, MÍREME!', FALSE, 2),
    ('SUB-2810', 'C', 'HACERLE SABER EL MOTIVO DE LA INTERVENCIÓN, POR EJEMPLO: ES USTED SOSPECHOSO DE ........ O HA COMETIDO EL DELITO DE ........', FALSE, 3),
    ('SUB-2810', 'D', 'INDICARLE QUE SE LE VA A IDENTIFICAR Y REGISTRAR, PARA QUE ASÍ PUEDA COLABORAR CON LA INTERVENCIÓN. DE SER NECESARIO, ORDENAR QUE ADOPTE UNA POSICIÓN APROPIADA PARA LA INMOVILIZACIÓN TEMPORAL (COLOCÁNDOLE LOS GRILLETES) Y REALIZAR EL REGISTRO PRELIMINAR.', FALSE, 4),
    ('SUB-2810', 'E', 'CULMINADA LA INTERVENCIÓN SIN NOVEDAD, EL POLICÍA DE CONTACTO (P1) AGRADECERÁ SU COLABORACIÓN, DESPLAZÁNDOSE LUEGO HACIA LA UBICACIÓN DEL POLICÍA DE SEGURIDAD (P2), PARA QUE EL CIUDADANO REINICIE SU CAMINO ACOMPAÑÁNDOLO CON LA MIRADA HASTA CIERTA DISTANCIA.', TRUE, 5),
    ('SUB-2811', 'A', 'EFECTUAR UN REGISTRO CORPORAL DEL INTERVENIDO', FALSE, 1),
