    ('SUB-2811', 'E', 'EFECTUAR UN REGISTRO VISUAL DEL INTERVENIDO.', TRUE, 5),
    ('SUB-2812', 'A', 'EN EL MOMENTO QUE EL INTERVENIDO SE ENCUENTRA FRENTE AL POLICÍA QUE REALIZA EL CONTACTO VERBAL.', TRUE, 1),
    ('SUB-2812', 'B', 'EN EL MOMENTO QUE EL INTERVENIDO SE ENCUENTRA FRENTE AL EFECTIVO POLICIAL QUE REALIZA EL CONTACTO VISUAL.', FALSE, 2),
    ('SUB-2812', 'C', 'DESPUÉS QUE SE REALIZA EL CONTACTO VISUAL.', FALSE, 3),
    ('SUB-2812', 'D', 'EN EL MOMENTO QUE EL INTERVENIDO SE ENCUENTRA DISTANTE AL EFECTIVO POLICIAL QUE REALIZA EL CONTACTO VERBAL.', FALSE, 4),
    ('SUB-2812', 'E', 'EN EL MOMENTO QUE EL INTERVENIDO SE ENCUENTRA LEJOS AL EFECTIVO POLICIAL QUE REALIZA EL CONTACTO VERBAL.', FALSE, 5),
    ('SUB-2813', 'A', 'ES RECOMENDABLE EMPLEAR ESTA TÉCNICA CUANDO EL INFRACTOR SE ENCUENTRA EN UN AMBIENTE ABIERTO.', FALSE, 1),
    ('SUB-2813', 'B', 'ESTA POSICIÓN ES RECOMENDABLE CUANDO EN EL LUGAR DE LA INTERVENCIÓN EXISTE UN MURO, PARED, ETC. DONDE EL INFRACTOR SE PUEDA APOYARSE.', TRUE, 2),
    ('SUB-2813', 'C', 'EFECTUADO EL CONTACTO VISUAL E INICIADA LA VERBALIZACIÓN, SE ORDENARÁ AL INTERVENIDO COLOCARSE FRENTE A LOS POLICÍAS, A UNA DISTANCIA QUE PERMITA DOMINAR LA SITUACIÓN, FORMANDO EL CONO DE SEGURIDAD; SE LE INDICA QUE LEVANTE LOS BRAZOS, CON LAS MANOS TOTALMENTE ALEJADAS UNA DE OTRA Y LOS DEDOS SEPARADOS.', FALSE, 3),
    ('SUB-2813', 'D', 'ESTA POSICIÓN ES LA MÁS SEGURA, REPRESENTA MENOS RIESGO O POSIBILIDAD DE REACCIÓN DEL INFRACTOR. ES LA MÁS RECOMENDABLE CUANDO EXISTA MÁS DE UN INTERVENIDO.', FALSE, 4),
    ('SUB-2813', 'E', 'UTILIZANDO LA VERBALIZACIÓN SE ORDENARÁ AL INTERVENIDO UBICARSE FRENTE A LOS EFECTIVOS POLICIALES, A UNA DISTANCIA QUE LES PERMITA DOMINAR LA SITUACIÓN Y FORMAR EL CONO DE SEGURIDAD, INDICÁNDOLE QUE LEVANTE LOS BRAZOS, CON LAS MANOS TOTALMENTE ALEJADAS UNA DE OTRA Y LOS DEDOS SEPARADOS.', FALSE, 5),
