    ('SUB-2817', 'A', 'SE DEBE CONSIDERAR LAS CARACTERÍSTICAS DEL LUGAR DE LA INTERVENCIÓN (UBICACIÓN, ESTRUCTURAS DESCONOCIDAS, CALLEJONES, EDIFICACIONES, ILUMINACIÓN, ENTRE OTROS) QUE PUEDAN REPRESENTAR UN RIESGO PARA LA INTEGRIDAD DEL EFECTIVO POLICIAL O DE TERCEROS, ASÍ COMO EL POSIBLE APOYO DE OTRAS PERSONAS AL INFRACTOR', TRUE, 1),
    ('SUB-2817', 'B', 'EL EFECTIVO POLICIAL DEBE TENER EN CUENTA EL COMPORTAMIENTO DE LA PERSONA A INTERVENIR, QUE PUEDE SER DE COLABORACIÓN, RESISTENCIA PASIVA O ACTIVA, LLEGANDO INCLUSIVE A LA AGRESIÓN LETAL.', FALSE, 2),
