    ('SUB-2899', 'B', 'POR IDENTIFICACIÓN DEL CONDUCTOR, POR INFRACCIÓN AL CÓDIGO PENAL, Y POR PREVENCIÓN DE DELITOS Y FALTAS.', FALSE, 2),
    ('SUB-2899', 'C', 'PARA IDENTIFICAR AL PRESUNTO AUTOR DE UN DELITO, POR INFRACCIÓN AL REGLAMENTO DE TRÁNSITO, Y POR PREVENCIÓN DE DELITOS Y FALTAS.', FALSE, 3),
    ('SUB-2899', 'D', 'POR INFRACCIÓN AL REGLAMENTO NACIONAL DE TRÁNSITO; Y POR PREVENCIÓN DE DELITOS Y FALTAS.', TRUE, 4),
    ('SUB-2899', 'E', 'PARA IDENTIFICAR LOS DATOS DEL VEHÍCULO, POR INFRACCIÓN AL REGLAMENTO DE TRÁNSITO, Y POR PREVENCIÓN DE DELITOS Y FALTAS.', FALSE, 5),
    ('SUB-2900', 'A', 'ES RECOMENDABLE HACER DESCENDER, LUEGO DE HABER INTERVENIDO AL CONDUCTOR, A LOS OCUPANTES DEL ASIENTO DELANTERO POR LA PUERTA POSTERIOR IZQUIERDA (DETRÁS DE LA DEL CONDUCTOR), PARA MINIMIZAR LA POSIBILIDAD DE UNA TOMA DE REHÉN POR LOS OTROS INFRACTORES.', FALSE, 1),
    ('SUB-2900', 'B', 'ES RECOMENDABLE HACER DESCENDER, LUEGO DE HABER INTERVENIDO AL CONDUCTOR, AL (LOS) OCUPANTE(S) DEL ASIENTO TRASERO POR LA PUERTA POSTERIOR DERECHA (DETRÁS DE LA DEL CONDUCTOR), PARA MINIMIZAR LA POSIBILIDAD DE UNA TOMA DE REHÉN POR EL(LOS) OTRO(S) INFRACTOR(S).', FALSE, 2),
    ('SUB-2900', 'C', 'ES RECOMENDABLE HACER DESCENDER, LUEGO DE HABER INTERVENIDO AL CONDUCTOR, AL (LOS) OCUPANTE(S) DEL ASIENTO TRASERO POR LA PUERTA POSTERIOR IZQUIERDA (DETRÁS DE LA DEL CONDUCTOR), PARA MINIMIZAR LA POSIBILIDAD DE FUGA DEL (LOS) OTRO(S) INFRACTOR(S). Derechos Humanos aplicados a la Función Policial - 2da parte', FALSE, 3),
    ('SUB-2900', 'D', 'ES RECOMENDABLE HACER DESCENDER, LUEGO DE HABER INTERVENIDO AL CONDUCTOR, A LOS OCUPANTES DEL ASIENTO TRASERO POR LA PUERTA POSTERIOR IZQUIERDA (DETRÁS DE LA DEL CONDUCTOR), PARA MINIMIZAR LA POSIBILIDAD DE FUGA DE LOS OTROS OCUPANTES.', FALSE, 4),
