INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 2901 a 3000
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (2901, 'SUB-2901', 'SBM5', 'EN LA INTERVENCIÓN POLICIAL DIURNA A UN VEHÍCULO CON PRESUNTOS INFRACTORES DESDE UN VEHÍCULO POLICIAL, ANTE LA PRESENCIA DE UN TERCERO O MÁS OCUPANTES, ES RECOMENDABLE HACER DESCENDER, LUEGO DE HABER INTERVENIDO AL CONDUCTOR, A LOS OCUPANTES DEL ASIENTO TRASERO POR LA (. ), PARA MINIMIZAR LA POSIBILIDAD DE UNA TOMA DE REHÉN POR LOS OTROS INFRACTORES.', 'PUERTA POSTERIOR IZQUIERDA (DETRÁS DE LA DEL CONDUCTOR)', '2DA PARTE [CAPÍTULO III] - B.3.b', '186088'),
    (2902, 'SUB-2902', 'SBM5', 'RESPECTO A LAS TÉCNICAS DE INTERVENCIÓN,LOS PROCEDIMIENTOS DE LA INTERVENCIÓN POLICIAL PROPIAMENTE DICHA (IDENTIFICACIÓN, REDUCCIÓN, INMOVILIZACIÓN Y REGISTRO) DEBERÁN EFECTUARSE SIEMPRE EN LA ZONA DE SEGURIDAD. EL EFECTIVO POLICIAL JAMÁS INGRESARÁ A LA ZONA DE (. ................... ), SI ES QUE ÉSTA NO HA SIDO DEBIDAMENTE CONTROLADA.', 'RIESGO', '2DA PARTE [CAPÍTULO III] - A', '186089'),
    (2903, 'SUB-2903', 'SBM5', 'EN LA INTERVENCIÓN POLICIAL DIURNA A UN VEHÍCULO CON PRESUNTOS INFRACTORES DESDE UN VEHÍCULO POLICIAL, ANTE LA PRESENCIA DE UN TERCERO O MÁS OCUPANTES, INDIQUE EL PROCEDIMIENTO CORRECTO:', 'SE LES INDICARÁ QUE SAQUEN LAS MANOS POR LA VENTANA DEL LADO DERECHO', '2DA PARTE [CAPÍTULO III] - B.3.b', '186090'),
    (2904, 'SUB-2904', 'SBM5', 'EXISTEN EN LA ACTUALIDAD EQUIPAMIENTOS POLICIALES BASADOS EN EL EMPLEO DE ESPEJOS (PERISCOPIO, PLANCHA DE IDENTIFICACIÓN, ESPEJO TÁCTICO, ENTRE OTROS); SU USO BRINDA MAYOR SEGURIDAD AL EFECTIVO POLICIAL, PUES EVITA EXPONER PARTE DE SU CUERPO PARA REALIZAR LA (. ................ ), FACILITANDO SU MANTENIMIENTO EN LA ZONA DE ABRIGO O PARAPETO', 'OBSERVACIÓN', '2DA PARTE [CAPÍTULO III] - B.4.i', '186091'),
    (2905, 'SUB-2905', 'SBM5', '¿CUÁL ES EL OBJETIVO FUNDAMENTAL DEL USO DIFERENCIADO Y PROGRESIVO DE LA FUERZA POR PARTE DEL PERSONAL POLICIAL, SEGÚN EL MARCO NORMATIVO ANALIZADO?', 'ADAPTAR LOS MEDIOS Y MÉTODOS DE INTERVENCIÓN SEGÚN EL NIVEL DE COOPERACIÓN, RESISTENCIA O AGRESIÓN DE LA PERSONA O SITUACIÓN CONTROLADA', '2DA PARTE [CAPÍTULO II] - B', '186092'),
    (2906, 'SUB-2906', 'SBM5', 'EN EL MARCO DEL USO PROGRESIVO DE LA FUERZA, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES DEFINE CON MAYOR PRECISIÓN LA "RESISTENCIA PASIVA-NO COOPERADOR"?', 'EL INTERVENIDO NO ACATA LAS INDICACIONES. NO REACCIONA NI AGREDE', '2DA PARTE [CAPÍTULO II] - B.1.a.(3)', '186093'),
    (2907, 'SUB-2907', 'SBM5', 'EN RELACIÓN A LOS NIVELES PREVENTIVOS DEL USO DE LA FUERZA, ¿CUÁL DE LAS SIGUIENTES ALTERNATIVAS CORRESPONDE A LA AL PRESENCIA POLICIAL?', 'DEMOSTRACIÓN DE AUTORIDAD DEL PERSONAL DE LA POLICIA NACIONAL UNIFORMADO O DEBIDAMENTE IDENTIFICADO, SU PLACA INSIGNIA Y CARNET DE IDENTIDAD DEBIDAMENTE EQUIPADO.', '2DA PARTE [CAPÍTULO II] - B.2.a.(1)', '186094'),
    (2908, 'SUB-2908', 'SBM5', 'DE ACUERDO AL TEXTO, ¿CUÁNDO CORRESPONDE UTILIZAR LA FUERZA POTENCIALMENTE LETAL SEGÚN EL USO DIFERENCIADO Y PROGRESIVO DE LA FUERZA?', 'CUANDO EXISTE UN PELIGRO REAL E INMINENTE DE MUERTE O LESIONES GRAVES CON EL OBJETIVO DE CONTRATARLO Y DEFENDER LA VIDA PROPIA O DE OTRAS PERDONAS.', '2DA PARTE [CAPÍTULO II] - B.2.b.(3)', '186095'),
    (2909, 'SUB-2909', 'SBM5', 'RESPECTO AL "CONTROL DE CONTACTO", ¿CUÁL ES SU PRINCIPAL OBJETIVO DENTRO DE LOS NIVELES DEL USO DE LA FUERZA?', 'GUIAR Y CONTENER LA ACCIÓN O ACTUTUD DE LA PERSONA, MEDIANTE TÉCNICAS DE COMUNICACIÓN Y NEGOCIACIÓN, SIN LLEGAR AL CONTROL FÍSICO.', '2DA PARTE [CAPÍTULO II] - B.2.a.(3)', '186096'),
    (2910, 'SUB-2910', 'SBM5', 'DE LOS SIGUIENTES CONCEPTOS, ¿CUÁL DEFINE MEJOR LA AGRESIÓN NO LETAL DENTRO DE LA RESISTENCIA ACTIVA?', 'USO DE FUERZA CORPORAL U OBJETO PELIGROSO QUE ATENTA CONTRA LA INTEGRIDAD FÍSICA, SIN GENERAR PELIGRO REAL E INMINENTE DE MUERTE O LESIONES GRAVES', '2DA PARTE [CAPÍTULO II] - B.1.b.(2)', '186099'),
    (2911, 'SUB-2911', 'SBM5', '¿EN QUÉ MOMENTO Y CÓMO DEBE APLICARSE LA VERBALIZACIÓN EN EL USO PROGRESIVO DE LA FUERZA POLICIAL?', 'EN TODOS LOS NIVELES DEL USO DE LA FUERZA COMO PRIMER MÉTODO DE COMUNICACIÓN Y CONTROL.', '2DA PARTE [CAPÍTULO II] - B.2.a.(2)', '186100'),
    (2912, 'SUB-2912', 'SBM5', '¿A QUÉ SE REFIERE EL "RIESGO LATENTE" EN LA RESISTENCIA PASIVA?', 'A LA AMENAZA PERMANENTE NO VISIBLE, DERIVADA DE FACTORES SOCIALES, ECONÓMICOS O GEOGRÁFICOS PRESENTES EN TODA INTERVENCIÓN.', '2DA PARTE [CAPÍTULO II] - B.1.a.(1)', '186101'),
    (2913, 'SUB-2913', 'SBM5', '¿CUÁL DE LAS SIGUIENTES ALTERNATIVAS EXPRESA CORRECTAMENTE EL CONCEPTO DE "CONTROLAR" SEGÚN EL NIVEL REACTIVO?', 'EL RESULTADO OBTENIDO DE REDUCIR, INMOVILIZAR Y CONDUCIR AL INTERVENIDO', '2DA PARTE [CAPÍTULO II] - B.2.b.(1)', '186102'),
    (2914, 'SUB-2914', 'SBM5', 'DENTRO DEL ESPECTRO DEL USO PROGRESIVO DE LA FUERZA, ¿QUÉ CARACTERÍSTICA DIFERENCIA LA REDUCCIÓN DE LA INMOVILIZACIÓN?', 'LA REDUCCIÓN CONSISTE EN MINIMIZAR LA RESISTENCIA FÍSICA, Y LA INMOVILIZACIÓN EN IMPEDIR TEMPORALMENTE LA MOVILIDAD CORPORAL MEDIANTE GRILLETES.', '2DA PARTE [CAPÍTULO II] - B.2.b.(1)', '186103'),
    (2915, 'SUB-2915', 'SBM5', '¿QUÉ CARACTERIZA PRINCIPALMENTE AL "COOPERADOR" EN LA RESISTENCIA PASIVA SEGÚN EL TEXTO ANALIZADO?', 'EL INTERVENIDO ACATA TODAS LAS INDICACIONES DEL EFECTIVO POLICIAL, SIN RESISTENCIA MANIFIESTA DURANTE LA INTERVENCIÓN', '2DA PARTE [CAPÍTULO II] - B.1.a.(2)', '186108'),
    (2916, 'SUB-2916', 'SBM5', 'CON RELACIÓN A LOS PRINCIPIOS INTERNACIONALES SOBRE EL USO DE LA FUERZA APLICABLES A LA FUNCIÓN POLICIAL, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES DESCRIBE CORRECTAMENTE EL PRINCIPIO DE LEGALIDAD?', 'EXIGE QUE EL USO DE LA FUERZA ESTÉ ORIENTADO AL LOGRO DE UN OBJETIVO LEGAL Y AMPARADOS EN EL MARCO DEL DERECHO INTERNACIONAL DE DERECHOS HUMANOS, CONSTITUCION POLITICA DEL PERU Y NORMAS NACIONALES SOBRE LA MATERIA.', '2DA PARTE [CAPÍTULO II] - A.1', '186117'),
    (2917, 'SUB-2917', 'SBM5', 'SEGÚN EL TEXTO, ¿CUÁNDO EL USO DE LA FUERZA POR PARTE DE LA POLICÍA NACIONAL DEL PERÚ SE CONVIERTE EN VIOLENCIA?', 'CUANDO SU EMPLEO ES EXCESIVO, ARBITRARIO Y NO PROFESIONAL, CON LO QUE DEBE QUEDAR CLARO PARA LOS EFECTIVOS POLICIALES.', '2DA PARTE [CAPÍTULO II]', '186123'),
    (2918, 'SUB-2918', 'SBM5', 'RESPECTO AL TRATO DEL PERSONAL POLICIAL HACIA GRUPOS VULNERABLES, SEÑALE LA AFIRMACIÓN CORRECTA DE ACUERDO AL TEXTO.', 'SE DEBEN TOMAR CONSIDERACIONES ESPECIALES Y BRINDAR TRATO HUMANO Y DIGNO A MUJERES, NIÑOS, ADOLESCENTES, ADULTOS MAYORES Y PERSONAS CON DISCAPACIDAD.', '2DA PARTE [CAPÍTULO II]', '186125'),
    (2919, 'SUB-2919', 'SBM5', 'EN LA LÍNEA DE LOS PRINCIPIOS DE DDHH APLICADOS A LA FUNCIÓN POLICIAL, ¿QUÉ ACCIÓN DEBE IMPLEMENTAR LA INSTITUCIÓN POLICIAL PARA REDUCIR EL USO EXCESIVO DE LA FUERZA?', 'CAPACITACIÓN EN SOLUCIÓN PACÍFICA DE CONFLICTOS, ESTUDIO DE COMPORTAMIENTO DE MULTITUDES Y NEGOCIACIÓN', '2DA PARTE [CAPÍTULO II]', '186126'),
    (2920, 'SUB-2920', 'SBM5', 'EN RELACIÓN AL CONTROL DEL USO DE LA FUERZA, ¿QUÉ MECANISMOS ESTABLECE EL TEXTO PARA SUPERVISAR Y SANCIONAR POTENCIALES EXCESOS?', 'INVESTIGACIONES Y SANCIONES ANTE PRESENTARSE EXCESOS EN EL USO DE LA FUERZA', '2DA PARTE [CAPÍTULO II]', '186127'),
    (2921, 'SUB-2921', 'SBM5', 'INDIQUE CUÁL DE LAS SIGUIENTES ATRIBUCIONES CORRESPONDE A LA POLICÍA NACIONAL DEL PERÚ SEGÚN LA LEY MENCIONADA EN LOS CONCEPTOS PREVIOS.', 'APLICAR EL USO DE LA FUERZA CONFORME A LA NORMA, CÓDIGO DE CONDUCTA Y PRINCIPIOS BÁSICOS SOBRE SU EMPLEO, EN EL MARCO DE LOS ACUERDOS DE LA ONU.', '2DA PARTE [CAPÍTULO II]', '186129'),
    (2922, 'SUB-2922', 'SBM5', 'LA LEGITIMIDAD DEL ACCIONAR POLICIAL AL HACER USO DE LA FUERZA QUEDA ASEGURADA SOLAMENTE SI:', 'SE EJECUTA CONFORME A LA LEY Y RESPETANDO LOS DERECHOS HUMANOS.', '2DA PARTE [CAPÍTULO II]', '186130'),
    (2923, 'SUB-2923', 'SBM5', '¿CUÁL ES LA FINALIDAD PRINCIPAL DE INFORMAR AL PERSONAL POLICIAL SOBRE LA OPERACIÓN ANTES DE SU EJECUCIÓN EN EL CONTEXTO DE MANTENIMIENTO DEL ORDEN PÚBLICO?', 'BRINDAR AL PERSONAL CONOCIMIENTO DE LA MISIÓN Y AUMENTAR LA GARANTIA DE CONFIANZA Y SEGURIDAD PERSONAL', '2DA PARTE [CAPÍTULO IV] - C.1.[Imagen]', '186132'),
    (2924, 'SUB-2924', 'SBM5', 'SEGÚN LAS DISPOSICIONES ANALIZADAS, ¿EN QUÉ CIRCUNSTANCIAS ES LEGÍTIMO EL USO DE CUALQUIER MEDIO A SU ALCANCE POR PARTE DEL PERSONAL POLICIAL EN LA FUERZA POTENCIALMENTE LETAL?', 'EN CIRCUNSTANCIAS EXTREMAS DONDE REPRESENTA UN PELIGRO INMINENTE LA VIDA PROPIA O DE OTRAS PERSONAS', '2DA PARTE [CAPÍTULO IV] - C.2.p', '186133'),
    (2925, 'SUB-2925', 'SBM5', 'DURANTE UNA MANIFESTACIÓN, ¿CUÁL ES EL PROCEDIMIENTO CORRECTO FRENTE A LA PRESENCIA DE MUJERES, NIÑOS, ANCIANOS O PERSONAS CON DISCAPACIDAD, SEGÚN EL PROTOCOLO?', 'EVALUAR SU PARTICIPACIÓN PARA ADOPTAR MEDIOS DE DISUASIÓN, PROTECCIÓN Y/O CONTROL ADECUADOS.', '2DA PARTE [CAPÍTULO IV] - C.2.c', '186134'),
    (2926, 'SUB-2926', 'SBM5', '¿CUÁL ES LA RECOMENDACIÓN CENTRAL RESPECTO AL USO DEL EQUIPO POLICIAL (COMO GRILLETES, DEFENSA DE GOMA, AGENTES QUÍMICOS O ARMAS ESPECIALES) PACTADA PARA ANTES DE LA OPERACIÓN?', 'EL EQUIPO ES DE DEFENSA Y SE USARÁ SOLO CUANDO LAS CIRCUNSTANCIAS LO REQUIERAN O LA LÍNEA DE COMANDO LO DISPONGA', '2DA PARTE [CAPÍTULO IV] - C.1.d', '186135'),
    (2927, 'SUB-2927', 'SBM5', '¿CUÁL ES EL CRITERIO CLAVE PARA EL USO DIFERENCIADO Y PROPORCIONAL DE LA FUERZA RECOMENDADO AL PERSONAL POLICIAL?', 'LOS PRINCIPIOS DE LEGALIDAD, NECESIDAD Y PROPORCIONALIDAD.', '2DA PARTE [CAPÍTULO IV] - C.1.e', '186136'),
    (2928, 'SUB-2928', 'SBM5', '¿QUÉ RESTRICCIÓN ESPECÍFICA EXISTE SOBRE EL EMPLEO DE MATERIAL LACRIMÓGENO DURANTE LAS OPERACIONES?', 'SE EVITA SU USO EN INMEDIACIONES DE EDIFICACIONES DONDE SE CONGREGUEN PERSONAS CON MAYOR RIESGO, TALES COMO HOSPITALES, ASILOS, COLEGIOS', '2DA PARTE [CAPÍTULO IV] - C.2.g', '186138'),
    (2929, 'SUB-2929', 'SBM5', 'AL DISOLVER UNA MULTITUD, ¿CUÁL ES LA TÉCNICA RECOMENDADA PARA EVITAR EL AUMENTO DE LA RESISTENCIA DE LOS MANIFESTANTES?', 'TECNICA DE USO, DIVIDIR Y DISPERSAR EN EL SENTIDO O DIRECCIÓN DE LA VIA QUE SE HAYA PREVISTO.', '2DA PARTE [CAPÍTULO IV] - C.2.j', '186139'),
    (2930, 'SUB-2930', 'SBM5', 'SEGÚN LOS LINEAMIENTOS ESTUDIADOS, ¿CÓMO DEBE ACTUAR EL PERSONAL POLICIAL ANTE PERSONAS QUE HUYEN O CAEN Y NO PARTICIPAN EN HECHOS VIOLENTOS DURANTE OPERATIVOS?', 'NO HACER USO DE LA FUERZA CONTRA ELLOS Derechos Humanos aplicados a la Función Policial - 2da parte', '2DA PARTE [CAPÍTULO IV] - C.2.n', '186140'),
    (2931, 'SUB-2931', 'SBM5', '¿QUÉ ACCIÓN SE EXIGE INMEDIATAMENTE DESPUÉS DE UNA OPERACIÓN POLICIAL SI EXISTEN DETENIDOS, LESIONADOS O MUERTOS?', 'COMUNICAR DE INMEDIATO A SUS FAMILIARES.', '2DA PARTE [CAPÍTULO IV] - C.3.b', '186141'),
    (2932, 'SUB-2932', 'SBM5', 'EN EL CONTEXTO DEL USO DE LA FUERZA, ¿QUÉ OBLIGACIÓN TIENE EL PERSONAL QUE EMPLEE DEFENSA DE GOMA, AGENTES QUÍMICOS O ARMAS ESPECIALES?', 'FORMULARA EL PARTE CORRESPONDIENTE DE SU INTERVENCIÓN Y REGISTRAR LA EXISTENCIA DE DETENIDOS, HERIDOS O MUERTOS Y EL DETERIORO DEL EQUIPO POLICIAL.', '2DA PARTE [CAPÍTULO IV] - C.2.r', '186143'),
    (2933, 'SUB-2933', 'SBM5', '¿CUÁL ES EL CRITERIO PARA DEJAR DE EMPLEAR LA FUERZA DURANTE LA INTERVENCIÓN POLICIAL?', 'AL CESE DE LA RESISTENCIA O VIOLENCIA, ADOPTANDO MEDIDAS DE SEGURIDAD.', '2DA PARTE [CAPÍTULO IV] - C.2.q', '186144'),
    (2934, 'SUB-2934', 'SBM5', 'RESPECTO AL TRATO DE LOS ARRESTADOS O DETENIDOS, ¿QUÉ OBLIGACIÓN ESTABLECE DIRECTAMENTE LA DIRECTIVA LUEGO DE LA INTERVENCIÓN?', 'NINGUNA CIRCUNSTANCIA JUSTIFICA LA TORTURA NI TRATOS CRUELES, INHUMANOS O DEGRADANTES.', '2DA PARTE [CAPÍTULO IV] - C.3.c', '186145'),
    (2935, 'SUB-2935', 'SBM5', '¿CUÁL ES EL PROCEDIMIENTO CORRECTO ANTE PERSONAS QUE RESULTAN LESIONADAS DURANTE UNA INTERVENCIÓN POLICIAL?', 'EVACUARLOS A LOS CENTROS DE ATENCIÓN MÉDICA MÁS PRÓXIMOS Y GARANTIZAR CORREDORES HUMANITARIOS Y ACCESO DE SOCORRISTAS', '2DA PARTE [CAPÍTULO IV] - C.2.s', '186146'),
    (2936, 'SUB-2936', 'SBM5', 'EN EL EMPLEO DE TÉCNICAS Y TÁCTICAS DE MANTENIMIENTO DEL ORDEN PÚBLICO, ¿CUÁL ES EL PRINCIPIO FUNDAMENTAL EXIGIDO RESPECTO AL USO DE LA FUERZA DURANTE SE DISPERSEN REUNIONES NO VIOLENTAS?', 'SE PRIORIZA EL NIVEL PREVENTIVO DEL EMPLEO DE LA FUERZA.', '2DA PARTE [CAPÍTULO IV] - C.2.c', '186147'),
    (2937, 'SUB-2937', 'SBM5', '¿QUÉ CONDUCTA SE DEBE ADOPTAR PARA EVITAR EXACERBAR LOS ÁNIMOS DE LOS MANIFESTANTES DURANTE UNA INTERVENCIÓN, SEGÚN LO ESTUDIADO?', 'LIMITARSE AL DECOMISO DE OBJETOS CONTUNDENTES O PUNZO CORTANTES UTILIZABLES COMO ARMAS.', '2DA PARTE [CAPÍTULO IV] - C.2.l', '186148'),
    (2938, 'SUB-2938', 'SBM5', '¿QUÉ CAPACITACIÓN Y REQUISITOS DEBE REUNIR EL PERSONAL ENCARGADO DE UTILIZAR ESCOPETAS DE PERDIGONES DE GOMA Y LANZA GAS LACRIMÓGENO?', 'DEBE ESTAR DEBIDAMENTE CAPACITADO Y ENTRENADO CONFORME A DIRECTIVAS VIGENTES.', '2DA PARTE [CAPÍTULO IV] - C.2.h', '186149'),
    (2939, 'SUB-2939', 'SBM5', '¿SOBRE QUÉ ASPECTOS DEBE RECAER LA EVALUACIÓN FINAL DE CADA INTERVENCIÓN POLICIAL?', 'DESTACANDO LAS FORTALEZAS Y DEBILIDADES', '2DA PARTE [CAPÍTULO IV] - C.3.e', '186150'),
    (2940, 'SUB-2940', 'SBM5', '¿CUÁL ES LA OBLIGACIÓN RESPECTO A LA EVIDENCIA DE LOS HECHOS DURANTE LA OPERACIÓN POLICIAL?', 'PREVER EL EMPLEO DE EQUIPOS DE FILMACIÓN QUE PERMITAN PERENNIZAR LOS HECHOS Y FORTALECER LA EVIDENCIA DE LA INVESTIGACIÓN.', '2DA PARTE [CAPÍTULO IV] - C.1.c', '186151'),
    (2941, 'SUB-2941', 'SBM5', 'SI DURANTE UNA OPERACIÓN SURGEN HECHOS O SITUACIONES NO PREVISTAS, ¿CÓMO DEBEN PROCEDER LOS JEFES OPERATIVOS SEGÚN LAS PAUTAS ANALIZADAS?', 'ACTUAR EN BASE A SUS CONOCIMIENTOS Y EXPERIENCIA, DISPONIENDO LAS MEDIDAS NECESARIAS PARA SUPERARLAS.', '2DA PARTE [CAPÍTULO IV] - C.2.t', '186152'),
    (2942, 'SUB-2942', 'SBM5', 'SEGÚN LA GUÍA, ¿QUÉ ACCIÓN ESTÁ PROHIBIDA PARA EL NEGOCIADOR DURANTE LA INTERVENCIÓN CON UN CAUSANTE?', 'IGNORAR EL CONTACTO CON EL CAUSANTE.', '2DA PARTE [CAPÍTULO V] - E.6.a', '186154'),
    (2943, 'SUB-2943', 'SBM5', '¿CUÁL DE LAS SIGUIENTES PRÁCTICAS ESTÁ EN CONCORDANCIA CON LOS DDHH APLICADOS A LA FUNCIÓN POLICIAL SEGÚN LA GUÍA ANALIZADA?', 'IMPLICAR A UN SEGUNDO NEGOCIADOR DURANTE EL PROCESO.', '2DA PARTE [CAPÍTULO V] - E.5.a', '186155'),
    (2944, 'SUB-2944', 'SBM5', 'EN UNA SITUACIÓN DE CRISIS, ¿QUIÉN DEBE ENTREGAR ALIMENTOS, MEDICINAS O ROPA AL CAUSANTE SEGÚN LA GUÍA?', 'OTRA PERSONA DISTINTA AL NEGOCIADOR', '2DA PARTE [CAPÍTULO V] - E.5.l y m', '186157'),
    (2945, 'SUB-2945', 'SBM5', 'DE ACUERDO A LOS PRINCIPIOS DE LA GUÍA, ¿QUÉ ACTITUD DEBE ADOPTAR EL NEGOCIADOR RESPECTO A LAS EMOCIONES DEL CAUSANTE?', 'REACCIONAR CON SENSIBILIDAD PARA ESTABLECER EMPATÍA Y CONTROL.', '2DA PARTE [CAPÍTULO V] - E.5.g', '186158'),
    (2946, 'SUB-2946', 'SBM5', '¿CÓMO DEBE PROCEDER EL NEGOCIADOR SI EL CAUSANTE LLEGA AL TIEMPO LÍMITE FIJADO DURANTE LAS CONVERSACIONES?', 'DISTRAER AL CAUSANTE Y GANAR TIEMPO DE NEGOCIACIÓN.', '2DA PARTE [CAPÍTULO V] - E.5.i', '186161'),
    (2947, 'SUB-2947', 'SBM5', 'DENTRO DE LA FUNCIÓN POLICIAL, UTILIZAR UNA VOZ QUE TRANSMITA SENTIMIENTOS DE COMPRENSIÓN, AMISTAD, CALIDEZ Y RESPETO BUSCA PRINCIPALMENTE:', 'CREAR UN AMBIENTE QUE FACILITE LA RENDICIÓN PACÍFICA Y LA PROTECCIÓN DE LOS DDHH.', '2DA PARTE [CAPÍTULO V] - E.5.e Derechos Humanos aplicados a la Función Policial - 2da parte', '186162'),
    (2948, 'SUB-2948', 'SBM5', 'SEÑALE LA CONDUCTA CONGRUENTE CON LA GUÍA APLICABLE A LA FUNCIÓN POLICIAL FRENTE A UN CAUSANTE ARMADO QUE SOLICITA DROGA O ALCOHOL:', 'NO ENTREGAR DROGA NI ALCOHOL, BAJO NINGÚN MOTIVO.', '2DA PARTE [CAPÍTULO V] - E.6.k', '186164'),
    (2949, 'SUB-2949', 'SBM5', '¿QUÉ DEBE EVITAR EL NEGOCIADOR PARA MANTENER LA LEGITIMIDAD DE LA FUNCIÓN POLICIAL ANTE UNA CRISIS QUE INVOLUCRA REHENES?', 'ACEPTAR AMENAZAS O ACTOS VIOLENTOS COMO JUSTIFICABLES.', '2DA PARTE [CAPÍTULO V] - E.6.j', '186165'),
    (2950, 'SUB-2950', 'SBM5', 'SEGÚN LAS BUENAS PRÁCTICAS INDICADAS, ¿POR QUÉ ES RELEVANTE TOMAR NOTA DE TODO LO SUCEDIDO DURANTE LA NEGOCIACIÓN?', 'PARA JUSTIFICAR LAS DECISIONES ANTE UNA PROBABLE INVESTIGACIÓN ADMINISTRATIVA O PENAL, Y SALVAGUARDAR LOS DDHH DE LAS PARTES.', '2DA PARTE [CAPÍTULO V] - E.5.c', '186166'),
    (2951, 'SUB-2951', 'SBM5', 'DESARROLLAR MEDIDAS PARA LA ATENCIÓN DE CASOS DE DESAPARICIÓN DE PERSONAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS, ABARCANDO LA ATENCIÓN DE DENUNCIAS, DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA, UBICACIÓN Y EMPLEO DE MECANISMOS TECNOLÓGICOS PARA LA ORGANIZACIÓN Y DIFUSIÓN DE INFORMACIÓN SOBRE CASOS DE DESAPARICIÓN DE PERSONAS. SE REFIERE AL:', 'OBJETO', 'ART. 1', '185859'),
    (2952, 'SUB-2952', 'SBM5', 'GARANTIZAR LA ATENCIÓN DE DENUNCIAS, DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA Y UBICACIÓN DE PERSONAS DE PERSONAS DESAPARECIDAS, ASÍ COMO PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'FINALIDAD', 'ART. 2, a.', '185860'),
    (2953, 'SUB-2953', 'SBM5', 'PROMOVER LA COOPERACIÓN ENTRE AUTORIDADES, ENTIDADES PÚBLICAS Y PRIVADAS, PERSONAS NATURALES Y JURÍDICAS, SOCIEDAD CIVIL Y COMUNIDAD EN GENERAL PARA LA DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA Y UBICACIÓN DE PERSONAS DESAPARECIDAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'FINALIDAD', 'ART. 2, b.', '185861'),
    (2954, 'SUB-2954', 'SBM5', 'IMPLEMENTAR MECANISMOS TECNOLÓGICOS PARA EL INTERCAMBIO DE INFORMACIÓN SOBRE CASOS DE DESAPARICIÓN DE PERSONAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'FINALIDAD', 'ART. 2, c.', '185862'),
    (2955, 'SUB-2955', 'SBM5', 'LA POLICÍA NACIONAL DEL PERÚ Y LAS INSTITUCIONES COMPRENDIDAS EN EL PRESENTE DECRETO LEGISLATIVO EJECUTAN DE FORMA OPORTUNA Y SIN DILACIONES TODAS LAS ACCIONES Y MEDIDAS ORIENTADAS A LA ATENCIÓN DE LA DENUNCIA, DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA Y UBICACIÓN DE PERSONAS DENUNCIADAS COMO DESAPARECIDAS. CORRESPONDE AL PRINCIPIO DE:', 'INMEDIATEZ', 'ART. 3, a.', '185863'),
    (2956, 'SUB-2956', 'SBM5', 'EN TODA MEDIDA QUE ADOPTE EL ESTADO A TRAVÉS DE LOS PODERES EJECUTIVO, LEGISLATIVO Y JUDICIAL, DEL MINISTERIO PÚBLICO, LOS GOBIERNOS REGIONALES, GOBIERNOS LOCALES Y SUS DEMÁS INSTITUCIONES, ASÍ COMO EN LA ACCIÓN DE LA SOCIEDAD, SE CONSIDERA DE MANERA PRIMORDIAL LA GARANTÍA Y PROTECCIÓN DE LOS DERECHOS DE LAS PERSONAS DESAPARECIDAS Y TODO CUENTO LE FAVORECE. CORRESPONDE AL PRINCIPIO DE:', 'INTERES SUPERIOR DE LA PERSONA DESAPARECIDA EN SITUACION DE VULNERABILIDAD', 'ART. 3, b.', '185864'),
    (2957, 'SUB-2957', 'SBM5', 'LAS AUTORIDADES, ENTIDADES PÚBLICAS Y PRIVADAS, SOCIEDAD CIVIL Y COMUNIDAD EN GENERAL BRINDAN APOYO A LA POLICÍA NACIONAL DEL PERÚ EN LA DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA Y UBICACIÓN DE PERSONAS DESAPARECIDAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS, EN EL MARCO DE LA OBLIGACIÓN SEÑALADA EN EL ARTÍCULO VI DEL TÍTULO PRELIMINAR DEL DECRETO LEGISLATIVO N° 1267, LEY DE LA POLICÍA NACIONAL DEL PERÚ. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'APOYO A LA POLICÍA NACIONAL DEL PERÚ', 'ART. 4, 4.1.', '185865'),
    (2958, 'SUB-2958', 'SBM5', 'LAS INSTITUCIONES PÚBLICAS O PRIVADAS APOYAN LA DIFUSIÓN DE LA NOTA DE ALERTA Y LA ALERTA AMBER UNA VEZ QUE LA POLICÍA NACIONAL DEL PERÚ HAYA DIFUNDIDO LA DESAPARICIÓN. PARA DICHO EFECTO, ESTAS INSTITUCIONES PONEN A DISPOSICIÓN DE LA AUTORIDAD POLICIAL LOS CANALES DE COORDINACIÓN Y ARTICULACIÓN PERTINENTES, INCLUYENDO LA ALERTA AMBER. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'APOYO A LA POLICÍA NACIONAL DEL PERÚ', 'ART. 4, 4.2.', '185866'),
    (2959, 'SUB-2959', 'SBM5', 'SE CONSIDERA PERSONA DESAPARECIDA A AQUELLA QUE SE ENCUENTRA AUSENTE DE SU DOMICILIO HABITUAL Y RESPECTO DEL CUAL SE DESCONOCE SU PARADERO. DEFINICIÓN QUE CORRESPONDE A:', 'PERSONA DESAPARECIDA', 'ART. 5, a.', '185867'),
    (2960, 'SUB-2960', 'SBM5', 'PERSONAS QUE SUFREN DISCRIMINACIÓN O SITUACIONES DE DESPROTECCIÓN, ENTRE ELLAS: NIÑAS, NIÑOS, ADOLESCENTES, PERSONAS ADULTAS MAYORES, PERSONAS CON DISCAPACIDAD, DESPLAZADOS, MIGRANTES, MUJERES VÍCTIMAS DE VIOLENCIA, INTEGRANTES DE PUEBLOS INDÍGENAS, PERSONAS LGTBQ+, SITUACIÓN DE POBREZA, ENTRE OTRAS PERSONAS QUE SE ENCUENTREN EN ESTA SITUACIÓN. DEFINICIÓN QUE CORRESPONDE A:', 'PERSONAS EN SITUACION DE VULNERABILIDAD', 'ART. 5, b.', '185868'),
    (2961, 'SUB-2961', 'SBM5', 'FORMATO EMITIDO POR LA POLICÍA NACIONAL DEL PERÚ POSTERIOR A LA RECEPCIÓN Y REGISTRO DE LA DENUNCIA POR DESAPARICIÓN DE UNA PERSONA EN EL SISTEMA DE DENUNCIAS DE LA POLICÍA NACIONAL DEL PERÚ. DEFINICIÓN QUE CORRESPONDE A:', 'NOTA DE ALERTA', 'ART. 5, C.', '185869'),
    (2962, 'SUB-2962', 'SBM5', 'CONTIENE INFORMACIÓN DE LA DENUNCIA Y FOTOGRAFÍA VISIBLE Y ACTUALIZADA DE LA PERSONA DESAPARECIDA Y ES DIFUNDIDA A TRAVÉS DEL PORTAL DE PERSONAS DESAPARECIDAS Y OTROS MEDIOS DE COMUNICACIÓN SOCIAL. DEFINICIÓN QUE CORRESPONDE A:', 'NOTA DE ALERTA', 'ART. 5, c.', '185870'),
    (2963, 'SUB-2963', 'SBM5', 'FORMATO EMITIDO POR LA POLICÍA NACIONAL DEL PERÚ QUE RESUME LA NOTA DE ALERTA. SE EMITE PARA LOS CASOS DE DESAPARICIÓN DE NIÑAS, NIÑOS, ADOLESCENTES, PERSONAS CON DISCAPACIDAD Y MUJERES VÍCTIMAS DE VIOLENCIA EN SITUACIÓN DE ALTO RIESGO. DEFINICIÓN QUE CORRESPONDE A:', 'ALERTA AMBER', 'ART. 5, d.', '185871'),
    (2964, 'SUB-2964', 'SBM5', 'ES TEMPORAL Y SU DIFUSIÓN ES MASIVA CON EL APOYO DE ENTIDADES PÚBLICAS Y PRIVADAS Y PERSONAS NATURALES Y JURÍDICAS. DEFINICIÓN QUE CORRESPONDE A:', 'ALERTA AMBER', 'ART. 5, d.', '185872'),
    (2965, 'SUB-2965', 'SBM5', 'ANTE LA AUSENCIA DE UNA PERSONA DE SU DOMICILIO HABITUAL Y DE LA CUAL SE DESCONOCE SU PARADERO, CUALQUIER PERSONA PUEDE PRESENTAR UNA DENUNCIA ANTE LA POLICÍA NACIONAL DEL PERÚ. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'PRESENTACION DE DENUNCIA', 'ART. 6, 6.1.', '185873'),
    (2966, 'SUB-2966', 'SBM5', 'LA DENUNCIA SE PRESENTA EN CUALQUIER MOMENTO ANTE LA POLICÍA NACIONAL DEL PERÚ. CUANDO LA DENUNCIA SE PRESENTA POR PERSONAS CUYA LENGUA MATERNA ES DISTINTA AL CASTELLANO, PERSONA CON DISCAPACIDAD, PERSONA ADULTA MAYOR U, OTRA SITUACIÓN DE VULNERABILIDAD, LA POLICÍA NACIONAL DEL PERÚ GARANTIZA SU ATENCIÓN CONFORME A LAS DIRECTIVAS, LINEAMIENTOS Y PROTOCOLOS VIGENTES. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'PRESENTACION DE DENUNCIA', 'ART. 6, 6.2.', '185874'),
    (2967, 'SUB-2967', 'SBM5', 'EL FUNCIONARIO, SERVIDOR PÚBLICO O PERSONAL QUE LABORE EN UNA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA QUE TOME CONOCIMIENTO SOBRE ALGÚN CASO DE DESAPARICIÓN DE PERSONAS DESAPARECIDAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS DEBE COMUNICAR DE FORMA INMEDIATA CON LA POLICÍA NACIONAL DEL PERÚ. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'PRESENTACION DE LA DENUNCIA', 'ART. 6, 6.3.', '185875'),
    (2968, 'SUB-2968', 'SBM5', 'LA POLICÍA NACIONAL DEL PERÚ ATIENDE LAS DENUNCIAS SOBRE DESAPARICIÓN DE MANERA INMEDIATA Y EN CUALQUIER MOMENTO, ENCONTRÁNDOSE A CARGO DE SU RECEPCIÓN Y TRÁMITE, BAJO RESPONSABILIDAD FUNCIONAL. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'ATENCIÓN DE LA DENUNCIA', 'ART. 7, 7.1.', '185876'),
    (2969, 'SUB-2969', 'SBM5', 'NO ES NECESARIO QUE TRANSCURRAN VEINTICUATRO (24) HORAS DESDE LA TOMA DE CONOCIMIENTO DE LA DESAPARICIÓN PARA ATENDER LA DENUNCIA. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'ATENCIÓN DE LA DENUNCIA', 'ART. 7, 7.1.', '185877'),
    (2970, 'SUB-2970', 'SBM5', 'LA POLICÍA NACIONAL DEL PERÚ RECIBE LA DENUNCIA, LA REGISTRA EN EL SISTEMA DE DENUNCIAS POLICIALES (SIDPOL) O EN EL SISTEMA DE REGISTRO DE DENUNCIAS DE INVESTIGACIÓN CRIMINAL (SIRDIQ), E INSCRIBE LA INFORMACIÓN EN EL REGISTRO NACIONAL DE INFORMACIÓN DE PERSONAS DESAPARECIDAS. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'ATENCIÓN DE LA DENUNCIA', 'ART. 7, 7.3.', '185878'),
    (2971, 'SUB-2971', 'SBM5', 'EN EL CASO DE QUE LA DENUNCIA NO FUESE RECIBIDA EN FORMA INMEDIATA POR LA POLICÍA NACIONAL DEL PERÚ, LA PERSONA AFECTADA PUEDE DENUNCIAR ESTE HECHO A LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ Y/O A LA CENTRAL ÚNICA DE DENUNCIAS DEL MINISTERIO DEL INTERIOR, SEGÚN CORRESPONDA. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'ATENCIÓN DE LA DENUNCIA', 'ART. 7, 7.3.', '185879'),
    (2972, 'SUB-2972', 'SBM5', 'LA POLICÍA NACIONAL DEL PERÚ ES RESPONSABLE DE INVESTIGAR Y REALIZAR LA BÚSQUEDA DE PERSONAS DESAPARECIDAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS; Y, DE INVESTIGAR LA COMISIÓN DE DELITOS CONCURRENTES, EN COORDINACIÓN CON EL MINISTERIO PÚBLICO. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'INVESTIGACIÓN Y BÚSQUEDA DE PERSONAS DENUNCIADAS COMO DESAPARECIDAS', 'ART. 9, 9.1.', '185880'),
    (2973, 'SUB-2973', 'SBM5', 'SI DE LAS CIRCUNSTANCIAS EN QUE SE TOMA CONOCIMIENTO LA DESAPARICIÓN Y/O INVESTIGACIÓN POLICIAL, SE DETERMINE O COMPRUEBE LA PRESENCIA DE DELITOS CONCURRENTES, LOS ÓRGANOS ESPECIALIZADOS DE LA POLICÍA NACIONAL DEL PERÚ ARTICULAN ESFUERZOS E INTERVIENEN, CONFORME A SUS PROCEDIMIENTOS OPERATIVOS Y NORMATIVA APLICABLE. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'INVESTIGACIÓN Y BÚSQUEDA DE PERSONAS DENUNCIADAS COMO DESAPARECIDAS', 'ART. 9, 9.2.', '185881'),
    (2974, 'SUB-2974', 'SBM5', 'LAS AUTORIDADES, ENTIDADES PÚBLICAS Y PRIVADAS, PERSONAS NATURALES Y JURÍDICAS, SOCIEDAD CIVIL Y COMUNIDAD EN GENERAL ESTÁN OBLIGADAS A PRESTAR APOYO A LA POLICÍA NACIONAL DEL PERÚ EN LA INVESTIGACIÓN Y BÚSQUEDA DE PERSONAS DESAPARECIDAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS, CUANDO LAS CIRCUNSTANCIAS ASÍ LO REQUIERAN, EN EL CUMPLIMIENTO DE SUS FUNCIONES. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'INVESTIGACIÓN Y BÚSQUEDA DE PERSONAS DENUNCIADAS COMO DESAPARECIDAS', 'ART. 9, 9.3.', '185882'),
    (2975, 'SUB-2975', 'SBM5', 'LA POLICÍA NACIONAL DEL PERÚ PUEDE UTILIZAR LA GEOLOCALIZACIÓN CUANDO CONSTITUYA UN MEDIO NECESARIO PARA LA INVESTIGACIÓN Y BÚSQUEDA DE PERSONAS DESAPARECIDAS. LA PRESENTE MEDIDA SERÁ EJECUTADA A TRAVÉS DE LA UNIDAD ESPECIALIZADA DE LA POLICÍA NACIONAL DEL PERÚ QUE REALICE DICHA FUNCIÓN. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'INVESTIGACIÓN Y BÚSQUEDA DE PERSONAS DENUNCIADAS COMO DESAPARECIDAS', 'ART. 9, 9.4.', '185883'),
    (2976, 'SUB-2976', 'SBM5', 'LAS AUTORIDADES ENCARGADAS DE DETERMINAR Y PROPORCIONAR LA AUTORIZACIÓN E INFORMACIÓN DE LA GEOLOCALIZACIÓN, SE RIGEN POR EL PRINCIPIO DE INMEDIATEZ; BAJO RESPONSABILIDAD ADMINISTRATIVA Y PENAL. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'INVESTIGACIÓN Y BÚSQUEDA DE PERSONAS DENUNCIADAS COMO DESAPARECIDAS', 'ART. 9, 9.4.', '185884'),
    (2977, 'SUB-2977', 'SBM5', 'LAS EMPRESAS OPERADORAS DE TELEFONÍA MÓVIL Y TELEFONÍA FIJA PROPORCIONAN EL LISTADO DE NÚMEROS TELEFÓNICOS DE LLAMADAS ENTRANTES Y SALIENTES, CON LOS NOMBRES Y APELLIDOS DE LOS TITULARES, DE LAS LÍNEAS TELEFÓNICAS VINCULADAS A LA DESAPARICIÓN DE PERSONAS QUE REQUIERA LA POLICÍA NACIONAL DEL PERÚ, OBSERVANDO LO DISPUESTO POR EL ARTÍCULO 2, INCISO 10 DE LA CONSTITUCIÓN POLÍTICA DEL PERÚ. EN EL REGLAMENTO DEL PRESENTE DECRETO LEGISLATIVO SE REGULA EL PERIODO DE LA INFORMACIÓN REQUERIDA. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'INVESTIGACIÓN Y BÚSQUEDA DE PERSONAS DENUNCIADAS COMO DESAPARECIDAS', 'ART. 9, 9.5.', '185885'),
    (2978, 'SUB-2978', 'SBM5', 'CUALQUIER ENTIDAD PÚBLICA O PRIVADA Y PERSONA NATURAL O JURÍDICA QUE UBIQUE O CUENTE CON INFORMACIÓN SOBRE UNA PERSONA DESAPARECIDA, ASÍ COMO PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS DEBE COMUNICARSE INMEDIATAMENTE CON LA POLICÍA NACIONAL DEL PERÚ, A TRAVÉS DE LOS CANALES Y PROCEDIMIENTOS HABILITADOS PARA LA RECEPCIÓN DE INFORMACIÓN, CONFORME LO SEÑALADO EN EL REGLAMENTO DEL PRESENTE DECRETO LEGISLATIVO. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'INFORMACIÓN SOBRE PERSONAS DENUNCIADAS COMO DESAPARECIDAS', 'ART. 10, 10.1.', '185886'),
    (2979, 'SUB-2979', 'SBM5', 'CUANDO EL DENUNCIANTE UBIQUE O TOME CONOCIMIENTO DE LA UBICACIÓN DE LA PERSONA DESAPARECIDA, ASÍ COMO DE LA PERSONA EN SITUACIÓN DE VULNERABILIDAD DENUNCIADA COMO DESAPARECIDA, DEBE COMUNICAR ESTA SITUACIÓN INMEDIATAMENTE A LA POLICÍA NACIONAL DEL PERÚ. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'INFORMACIÓN SOBRE PERSONAS DENUNCIADAS COMO DESAPARECIDAS', 'ART. 10, 10.2.', '185887'),
    (2980, 'SUB-2980', 'SBM5', 'LAS ENTIDADES PÚBLICAS, EN EL MARCO DE SUS COMPETENCIAS, BRINDAN APOYO A LA POLICÍA NACIONAL DEL PERÚ EN MATERIA DE PREVENCIÓN, DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA Y UBICACIÓN DE PERSONAS DESAPARECIDAS, ASÍ COMO DE LAS PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS, Y EN SU ATENCIÓN CUANDO HA SIDO UBICADAS. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'ARTICULACIÓN ESTATAL', 'ART. 11', '185888'),
    (2981, 'SUB-2981', 'SBM5', 'LAS MEDIDAS ADOPTADAS ESTÁN ORIENTADAS A SALVAGUARDAR LA INTEGRIDAD Y VIDA DE LA PERSONA DESAPARECIDA. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'ARTICULACIÓN ESTATAL', 'ART. 11', '185889'),
    (2982, 'SUB-2982', 'SBM5', 'RESPECTO A LA ARTICULACION ESTATAL, DESTACAN LAS SIGUIENTES ACCIONES MÍNIMAS, MARQUE LA ALTERNATIVA CORRECTA:', 'DIFUSIÓN DEL PROCEDIMIENTO DE ATENCIÓN DE DENUNCIA Y SENSIBILIZACION DE CASOS DE DESAPARICION, CON EL APOYO DEL MINISTERIO DE EDUCACIÓN', 'ART. 11, a.', '185890'),
    (2983, 'SUB-2983', 'SBM5', 'RESPECTO A LA ARTICULACION ESTATAL, DESTACAN LAS SIGUIENTES ACCIONES MÍNIMAS, MARQUE LA ALTERNATIVA CORRECTA:', 'DIFUSIÓN Y COLABORACIÓN EN LAS LABORES DE DIFUSIÓN Y BÚSQUEDA, CON EL APOYO DEL MINISTERIO DE TRANSPORTES Y COMUNICACIONES', 'ART. 11, b.', '185891'),
    (2984, 'SUB-2984', 'SBM5', 'RESPECTO A LA ARTICULACION ESTATAL, DESTACAN LAS SIGUIENTES ACCIONES MÍNIMAS, MARQUE LA ALTERNATIVA CORRECTA:', 'COLABORACIÓN EN LAS LABORES DE BÚSQUEDA Y', 'ART. 11, d.', '185892'),
    (2985, 'SUB-2985', 'SBM5', 'RESPECTO A LA ARTICULACION ESTATAL, DESTACAN LAS SIGUIENTES ACCIONES MÍNIMAS, MARQUE LA ALTERNATIVA CORRECTA:', 'COLABORACIÓN EN LABORES DE DIFUSIÓN,', 'ART. 11, f.', '185893'),
    (2986, 'SUB-2986', 'SBM5', 'GARANTIZAR LA ATENCIÓN DE DENUNCIAS, DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA Y UBICACIÓN DE PERSONAS DE PERSONAS DESAPARECIDAS, ASÍ COMO PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'FINALIDAD', 'ART. 2, a.', '185894'),
    (2987, 'SUB-2987', 'SBM5', 'PROMOVER LA COOPERACIÓN ENTRE AUTORIDADES, ENTIDADES PÚBLICAS Y PRIVADAS, PERSONAS NATURALES Y JURÍDICAS, SOCIEDAD CIVIL Y COMUNIDAD EN GENERAL PARA LA DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA Y UBICACIÓN DE PERSONAS DESAPARECIDAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'FINALIDAD', 'ART. 2, b.', '185895'),
    (2988, 'SUB-2988', 'SBM5', 'IMPLEMENTAR MECANISMOS TECNOLÓGICOS PARA EL INTERCAMBIO DE INFORMACIÓN SOBRE CASOS DE DESAPARICIÓN DE PERSONAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS. EL PRESENTE ENUNCIADO CORRESPONDE A:', 'FINALIDAD', 'ART. 2, c.', '185896'),
    (2989, 'SUB-2989', 'SBM5', 'RESPECTO A LA ALERTA AMBER POR DESAPARICIÓN DE NIÑAS, NIÑOS Y ADOLESCENTES: (MARQUE LA ALTERNATIVA CORRECTA)', 'LA ALERTA AMBER SE EMITE PARA LOS CASOS DE DESAPARICIÓN DE NIÑAS, NIÑOS Y ADOLESCENTES DL 1428 - Medidas para la atención de casos de desaparición de personas en situación de vulnerabilidad', 'ART. 12, 12.1', '185897'),
    (2990, 'SUB-2990', 'SBM5', 'RESPECTO A LA ALERTA AMBER POR DESAPARICIÓN DE NIÑAS, NIÑOS Y ADOLESCENTES: (MARQUE LA ALTERNATIVA CORRECTA)', 'CULMINADO EL PERIODO DE TIEMPO ESTABLECIDO EN EL REGLAMENTO DEL PRESENTE DECRETO LEGISLATIVO, SE DESACTIVA LA ALERTA AMBER POR DESAPARICIÓN DE NIÑAS, NIÑOS Y ADOLESCENTES Y SE MANTIENE VIGENTE LA NOTA DE ALERTA', 'ART. 12, 12.2', '185898'),
    (2991, 'SUB-2991', 'SBM5', 'RESPECTO A LA INVESTIGACIÓN, BÚSQUEDA, UBICACIÓN Y ARTICULACIÓN CON ENTIDADES PÚBLICAS Y PRIVADAS, PARA LOS CASOS DE DESAPARICIÓN DE NIÑAS, NIÑOS Y ADOLESCENTES: (MARQUE LA ALTERNATIVA CORRECTA)', 'LAS ACCIONES DE INVESTIGACIÓN, BÚSQUEDA,', 'ART. 13, 13.1', '185899'),
    (2992, 'SUB-2992', 'SBM5', 'RESPECTO A LA ALERTA AMBER POR DESAPARICIÓN DE MUJERES VÍCTIMAS DE VIOLENCIA EN SITUACIÓN DE ALTO RIESGO', 'PARA EL CASO DE DESAPARICIÓN DE MUJERES VÍCTIMAS DE VIOLENCIA EN ALTO RIESGO TAMBIÉN SE EMITE UNA ALERTA AMBER Y SE REALIZAN ACCIONES DE BÚSQUEDA Y', 'ART. 14', '185900'),
    (2993, 'SUB-2993', 'SBM5', 'LA ORGANIZACIÓN Y CENTRALIZACIÓN DE INFORMACIÓN SOBRE CASOS DE DESAPARICIÓN DE PERSONAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS, SE REALIZA MEDIANTE EL REGISTRO NACIONAL DE INFORMACIÓN DE PERSONAS DESAPARECIDAS, REGULADO MEDIANTE LA… (MARQUE LA ALTERNATIVA CORRECTA)', 'LEY N° 28022', 'ART. 15', '185901'),
    (2994, 'SUB-2994', 'SBM5', 'LA DIFUSIÓN DE LOS CASOS DE DESAPARICIÓN DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD SE REALIZA MEDIANTE LAS… (MARQUE LA ALTERNATIVA CORRECTA)', 'NOTAS DE ALERTA Y ALERTAS AMBER', 'ART. 16', '185902'),
    (2995, 'SUB-2995', 'SBM5', 'RESPECTO A LA REGLAMENTACIÓN. EL MINISTERIO DEL INTERIOR ELABORA Y PROPONE EL PROYECTO DE REGLAMENTO DEL PRESENTE DECRETO LEGISLATIVO EN UN PLAZO NO MAYOR DE… (MARQUE LA ALTERNATIVA CORRECTA)', '(90) DÍAS', 'DISP. COMP. FIN. PRIMERA', '185903'),
    (2996, 'SUB-2996', 'SBM5', 'DESARROLLAR MEDIDAS PARA LA ATENCIÓN DE CASOS DE DESAPARICIÓN DE PERSONAS, ASÍ COMO DE PERSONAS EN SITUACIÓN DE VULNERABILIDAD DENUNCIADAS COMO DESAPARECIDAS, ABARCANDO LA ATENCIÓN DE DENUNCIAS, DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA, UBICACIÓN Y EMPLEO DE MECANISMOS TECNOLÓGICOS PARA LA ORGANIZACIÓN Y DIFUSIÓN DE INFORMACIÓN SOBRE CASOS DE DESAPARICIÓN DE PERSONAS. SE REFIERE AL:', 'OBJETO', 'ART. 1', '185904'),
    (2997, 'SUB-2997', 'SBM5', 'LA POLICÍA NACIONAL DEL PERÚ Y LAS INSTITUCIONES COMPRENDIDAS EN EL PRESENTE DECRETO LEGISLATIVO EJECUTAN DE FORMA OPORTUNA Y SIN DILACIONES TODAS LAS ACCIONES Y MEDIDAS ORIENTADAS A LA ATENCIÓN DE LA DENUNCIA, DIFUSIÓN, INVESTIGACIÓN, BÚSQUEDA Y UBICACIÓN DE PERSONAS DENUNCIADAS COMO DESAPARECIDAS. CORRESPONDE AL PRINCIPIO DE:', 'INMEDIATEZ', 'ART. 3, a.', '185905'),
    (2998, 'SUB-2998', 'SBM5', 'EN TODA MEDIDA QUE ADOPTE EL ESTADO A TRAVÉS DE LOS PODERES EJECUTIVO, LEGISLATIVO Y JUDICIAL, DEL MINISTERIO PÚBLICO, LOS GOBIERNOS REGIONALES, GOBIERNOS LOCALES Y SUS DEMÁS INSTITUCIONES, ASÍ COMO EN LA ACCIÓN DE LA SOCIEDAD, SE CONSIDERA DE MANERA PRIMORDIAL LA GARANTÍA Y PROTECCIÓN DE LOS DERECHOS DE LAS PERSONAS DESAPARECIDAS Y TODO CUENTO LE FAVORECE. CORRESPONDE AL PRINCIPIO DE:', 'INTERÉS SUPERIOR DE LA PERSONA DESAPARECIDA EN SITUACIÓN DE VULNERABILIDAD', 'ART. 3, b.', '185906'),
    (2999, 'SUB-2999', 'SBM5', 'SE CONSIDERA PERSONA DESAPARECIDA A AQUELLA QUE SE ENCUENTRA AUSENTE DE SU DOMICILIO HABITUAL Y RESPECTO DEL CUAL SE DESCONOCE SU PARADERO. DEFINICIÓN QUE CORRESPONDE A:', 'PERSONA DESAPARECIDA', 'ART. 5, a.', '185907'),
    (3000, 'SUB-3000', 'SBM5', '¿CUÁL ES LA DEPENDENCIA ENCARGADA DE EVALUAR Y ACTIVAR LA ALERTA AMBER SEGÚN EL ARTÍCULO 12-A DEL D. LEG. 1428?', 'LA DIVISIÓN DE INVESTIGACIÓN Y BÚSQUEDA DE PERSONAS DESAPARECIDAS', 'ART. 12-A', '185920')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

