INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- 3) Sincronizar totales
UPDATE banco_de_pregunta b
SET total_preguntas = t.cantidad
FROM (SELECT banco_id, COUNT(*)::int AS cantidad FROM pregunta GROUP BY banco_id) t
WHERE b.id = t.banco_id
  AND b.nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)'
  AND b.version = 'v1.0-pdf';

UPDATE materia m
SET total_preguntas_banco = t.cantidad, actualizado_at = NOW()
FROM (
  SELECT materia_id, COUNT(*)::int AS cantidad
  FROM pregunta WHERE codigo_pregunta LIKE 'SUB-%'
  GROUP BY materia_id
) t
WHERE m.id = t.materia_id;

COMMIT;

-- Verificacion
SELECT b.nombre, b.version, COUNT(p.id) AS total_preguntas FROM banco_de_pregunta b LEFT JOIN pregunta p ON p.banco_id = b.id WHERE b.nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND b.version = 'v1.0-pdf' GROUP BY b.nombre, b.version;
SELECT m.codigo, m.nombre, COUNT(p.id) AS total FROM materia m LEFT JOIN pregunta p ON p.materia_id = m.id WHERE m.codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5') GROUP BY m.codigo, m.nombre ORDER BY m.codigo;
